-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('a992ba3b-f9a5-5f2b-8ce8-b51ee22652b6'::uuid, 'fa46cacb-efc3-54b7-bf8e-27fb9084783a'::uuid, 'Qu’est-ce qu’un État de droit ?', 'mcq', '["Un État qui possède beaucoup de lois","Un État où le chef de l’État fait la loi seul","Un État où les gouvernants sont eux aussi soumis aux règles de droit","Un État sans juges"]'::jsonb, 2, 'Dans un État de droit, même l’État peut être sanctionné par un juge indépendant.', 1),
    ('7b794bac-74cd-50fc-b3ad-588a1e9a7a36'::uuid, 'fa46cacb-efc3-54b7-bf8e-27fb9084783a'::uuid, 'Quelle sanction distingue la règle de droit de la règle morale ?', 'mcq', '["Une sanction prononcée par l’autorité publique","La réprobation de l’entourage","Le remords","L’exclusion d’un groupe d’amis"]'::jsonb, 0, 'La règle de droit est assortie d’une sanction étatique : amende, dommages et intérêts, prison.', 2),
    ('b3701b9a-693c-51ef-b491-e2a2ae1f6fd1'::uuid, 'fa46cacb-efc3-54b7-bf8e-27fb9084783a'::uuid, 'Laquelle de ces fonctions n’est PAS une fonction du droit ?', 'mcq', '["Organiser la société","Protéger les personnes","Pacifier les relations sociales","Garantir le bonheur de chacun"]'::jsonb, 3, 'Le droit organise, protège, pacifie et fait évoluer la société ; le bonheur relève de la sphère personnelle.', 3),
    ('5ad3160d-3e73-5e45-a3fe-c15344bcbee8'::uuid, 'fa46cacb-efc3-54b7-bf8e-27fb9084783a'::uuid, 'Une règle d’ordre public peut être écartée si les deux parties au contrat sont d’accord.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Précisément : on ne peut pas y déroger par contrat. Un salaire sous le SMIC reste interdit même si le salarié l’accepte.', 4),
    ('d194b517-3f81-5dad-8bc1-a9af9bd7f4ab'::uuid, 'fa46cacb-efc3-54b7-bf8e-27fb9084783a'::uuid, 'La neutralité religieuse des agents publics découle du principe de…', 'mcq', '["Solidarité","Laïcité","Liberté contractuelle","Propriété"]'::jsonb, 1, 'La laïcité impose la neutralité de l’État et garantit la liberté de conscience de chacun.', 5),
    ('6c968d7e-d4c8-56bc-8280-e83a7343e204'::uuid, 'fa46cacb-efc3-54b7-bf8e-27fb9084783a'::uuid, 'Mentir à un ami est…', 'mcq', '["Un délit puni d’amende","Une contravention","Interdit par la Constitution","Contraire à la morale mais pas sanctionné par le droit"]'::jsonb, 3, 'Droit et morale se recoupent souvent, mais pas toujours.', 6),
    ('8b00770f-850b-5514-a764-9136490e765e'::uuid, 'fa46cacb-efc3-54b7-bf8e-27fb9084783a'::uuid, 'Quel texte de 1789 fonde les principes de liberté et d’égalité ?', 'mcq', '["La Déclaration des droits de l’homme et du citoyen","Le Code civil","La Constitution de 1958","Le traité de Rome"]'::jsonb, 0, 'La DDHC fait partie du « bloc de constitutionnalité » : elle a toujours valeur constitutionnelle.', 7),
    ('114662cf-8eaf-58ce-8127-6ce6b6e493e2'::uuid, 'fa46cacb-efc3-54b7-bf8e-27fb9084783a'::uuid, 'La protection des mineurs, des salariés et des consommateurs illustre la fonction…', 'mcq', '["D’organisation","De pacification","De protection","D’évolution"]'::jsonb, 2, 'Le droit rééquilibre les relations où l’une des parties est plus faible.', 8),
    ('e28f4d67-8bc4-5d56-b5a4-1c1741829670'::uuid, 'fa46cacb-efc3-54b7-bf8e-27fb9084783a'::uuid, 'L’adoption du RGPD en 2018 illustre surtout la fonction du droit qui consiste à…', 'mcq', '["Sanctionner les crimes","Organiser la famille","Fixer les impôts","Faire évoluer la société en suivant les changements techniques"]'::jsonb, 3, 'Le règlement européen sur les données personnelles répond à l’essor du numérique.', 9),
    ('e0b848a4-22ff-5ba0-a5ae-0a0693b68bbf'::uuid, 'fa46cacb-efc3-54b7-bf8e-27fb9084783a'::uuid, 'Le principe d’égalité interdit notamment…', 'mcq', '["De fixer des salaires différents selon le poste","La progressivité de l’impôt","Les discriminations fondées sur le sexe ou l’origine","La création d’entreprises"]'::jsonb, 2, 'L’égalité impose la même règle pour tous ceux qui sont dans la même situation.', 10),
    ('daae060c-74cf-55d0-b20b-595beb4ddaae'::uuid, 'fa46cacb-efc3-54b7-bf8e-27fb9084783a'::uuid, 'Qui décide de poursuivre l’auteur d’une infraction pénale ?', 'mcq', '["La victime seule","Le ministère public (procureur)","L’avocat de l’auteur","Le maire"]'::jsonb, 1, 'L’action publique appartient au ministère public ; la victime peut toutefois se constituer partie civile.', 11),
    ('bafcd304-e75b-5cfc-9789-25a7be956952'::uuid, 'fa46cacb-efc3-54b7-bf8e-27fb9084783a'::uuid, 'La solidarité, comme valeur du droit, se traduit par exemple par…', 'mcq', '["La Sécurité sociale","La liberté du commerce","Le droit de propriété","Le secret des affaires"]'::jsonb, 0, 'La collectivité prend en charge les risques de chacun : maladie, vieillesse, chômage.', 12),
    ('db31faf4-a3a7-5b4d-9972-375757c81aac'::uuid, '926b7152-d5fc-51ae-9d4c-7e5b600bb77f'::uuid, 'Quels sont les trois caractères de la règle de droit ?', 'mcq', '["Écrite, publique, gratuite","Morale, religieuse, coutumière","Générale, obligatoire, légitime","Nationale, européenne, internationale"]'::jsonb, 2, 'Générale (égalité), obligatoire (sanction), légitime (autorité compétente).', 1),
    ('6a1d1ede-0e48-58c0-a8b3-170a393e8408'::uuid, '926b7152-d5fc-51ae-9d4c-7e5b600bb77f'::uuid, 'Une règle générale s’applique…', 'mcq', '["À toutes les personnes placées dans la même situation juridique","À une personne désignée par son nom","Uniquement aux citoyens majeurs","Seulement en cas de litige"]'::jsonb, 0, 'Elle vise une catégorie, ce qui garantit l’égalité devant la loi.', 2),
    ('d41e03cd-b6e0-5237-9e2a-a14310a6d05a'::uuid, '926b7152-d5fc-51ae-9d4c-7e5b600bb77f'::uuid, 'Qu’est-ce que la qualification juridique ?', 'mcq', '["Le diplôme d’un avocat","La sanction prononcée par un juge","Le vote d’une loi","Le fait de classer des faits dans une catégorie juridique pour savoir quelle règle appliquer"]'::jsonb, 3, 'C’est l’opération clé du raisonnement juridique.', 3),
    ('7df44bea-1fb9-50d4-b0b3-9169cdabd41a'::uuid, '926b7152-d5fc-51ae-9d4c-7e5b600bb77f'::uuid, 'Le règlement intérieur d’une association sportive est une règle de droit étatique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il n’émane pas d’une autorité publique et n’est pas sanctionné par l’État ; il n’oblige que les membres.', 4),
    ('39d4152d-e90c-5585-893d-31a644f143f5'::uuid, '926b7152-d5fc-51ae-9d4c-7e5b600bb77f'::uuid, 'Dans quel code trouve-t-on les règles sur les contrats et la propriété ?', 'mcq', '["Le Code pénal","Le Code civil","Le Code du travail","Le Code de la route"]'::jsonb, 1, 'Le Code civil (1804) régit les personnes, les biens, les contrats et la responsabilité.', 5),
    ('4a5cd21e-884f-5f76-9494-b7197de1c3cd'::uuid, '926b7152-d5fc-51ae-9d4c-7e5b600bb77f'::uuid, 'Dans la méthode du cas pratique, que vient-il juste après la qualification des faits ?', 'mcq', '["La solution","La sanction","La plaidoirie","Le problème de droit"]'::jsonb, 3, 'On pose la question juridique générale avant de chercher la règle.', 6),
    ('1741ec9c-581b-5ebe-8fba-65563dae0c43'::uuid, '926b7152-d5fc-51ae-9d4c-7e5b600bb77f'::uuid, 'Une personne qui achète un vélo pour ses loisirs à un magasin se qualifie juridiquement comme…', 'mcq', '["Un consommateur","Un professionnel","Un commerçant","Un salarié"]'::jsonb, 0, 'Le consommateur est une personne physique qui agit hors de son activité professionnelle.', 7),
    ('a535d953-38b2-5a04-a4df-ff700d867d7d'::uuid, '926b7152-d5fc-51ae-9d4c-7e5b600bb77f'::uuid, 'Le caractère obligatoire de la règle de droit signifie que…', 'mcq', '["Elle est écrite dans un code","Elle a été votée à l’unanimité","Sa violation est sanctionnée par l’autorité publique","Elle est acceptée par la morale"]'::jsonb, 2, 'Sans sanction étatique possible, ce n’est pas une règle de droit.', 8),
    ('02939683-45fe-5940-821d-0b036a17bfd4'::uuid, '926b7152-d5fc-51ae-9d4c-7e5b600bb77f'::uuid, 'Quel est le délai de rétractation d’un consommateur pour un achat à distance ?', 'mcq', '["7 jours","10 jours","30 jours","14 jours"]'::jsonb, 3, '14 jours, sans justification, à compter de la réception du bien.', 9),
    ('c7623ea6-1de7-59a9-b52d-de1b82dea2a2'::uuid, '926b7152-d5fc-51ae-9d4c-7e5b600bb77f'::uuid, 'Pourquoi le droit utilise-t-il des catégories juridiques ?', 'mcq', '["Pour compliquer le travail des juges","Pour éviter d’écrire des codes","Parce qu’il ne peut pas décrire chaque situation de la vie","Parce que la morale l’exige"]'::jsonb, 2, 'La règle générale et abstraite vise des catégories, dans lesquelles on range les faits.', 10),
    ('461c0506-3f4f-5a5c-b4f2-17867aafa327'::uuid, '926b7152-d5fc-51ae-9d4c-7e5b600bb77f'::uuid, 'La légitimité d’une règle de droit tient au fait qu’elle…', 'mcq', '["Plaît à la majorité","Émane d’une autorité compétente","Est ancienne","Est courte"]'::jsonb, 1, 'Parlement, gouvernement, juge : chacun dans sa compétence.', 11),
    ('56d4f944-1378-52c8-be73-1ac507a07b88'::uuid, '926b7152-d5fc-51ae-9d4c-7e5b600bb77f'::uuid, '« Un vendeur a livré un produit défectueux » : quelle étape du cas pratique ce résumé constitue-t-il ?', 'mcq', '["L’exposé des faits","La solution","La règle","Le problème de droit"]'::jsonb, 0, 'Les faits se résument objectivement, avant toute qualification.', 12),
    ('69ad1379-2f46-56af-bcd8-d9cf0ed8ed4f'::uuid, 'e48fca4d-46b5-5f65-ae83-02a3bd740b74'::uuid, 'Quelle norme est au sommet de la hiérarchie des normes en droit interne ?', 'mcq', '["La loi","Le décret","La Constitution","La jurisprudence"]'::jsonb, 2, 'La Constitution de 1958 et son bloc de constitutionnalité dominent l’ordre juridique interne.', 1),
    ('d411588d-8ad9-55ab-bad1-7a4211a09037'::uuid, 'e48fca4d-46b5-5f65-ae83-02a3bd740b74'::uuid, 'Qui vote la loi en France ?', 'mcq', '["Le Parlement","Le Président de la République","Le Gouvernement","Le Conseil constitutionnel"]'::jsonb, 0, 'Le Parlement, composé de l’Assemblée nationale et du Sénat.', 2),
    ('64be32ef-f1fa-53af-b1cb-5707000ea31d'::uuid, 'e48fca4d-46b5-5f65-ae83-02a3bd740b74'::uuid, 'Un règlement européen…', 'mcq', '["Doit être transposé par une loi nationale","N’a aucune force obligatoire","Ne concerne que les institutions européennes","S’applique directement dans tous les États membres"]'::jsonb, 3, 'C’est la différence avec la directive, qui fixe un objectif à transposer.', 3),
    ('10c0a06c-24ed-5485-bf6b-8704aee5c3a8'::uuid, 'e48fca4d-46b5-5f65-ae83-02a3bd740b74'::uuid, 'Une directive européenne doit être transposée dans le droit national.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Chaque État choisit les moyens (sa loi) pour atteindre l’objectif fixé.', 4),
    ('3377646b-1d91-5203-b99e-09a674c69e05'::uuid, 'e48fca4d-46b5-5f65-ae83-02a3bd740b74'::uuid, 'Quel est le rôle de la Cour de cassation ?', 'mcq', '["Voter les lois","Unifier l’interprétation du droit par les juges","Contrôler les comptes publics","Juger les ministres"]'::jsonb, 1, 'Elle veille à ce que la même règle soit interprétée de la même manière partout en France.', 5),
    ('532da3bf-dab1-58d0-ac4c-40bb5ca3ad65'::uuid, 'e48fca4d-46b5-5f65-ae83-02a3bd740b74'::uuid, 'La QPC permet à un justiciable…', 'mcq', '["De proposer une loi","De faire appel d’un jugement","De saisir la Cour européenne des droits de l’homme","De contester une loi déjà en vigueur qui porterait atteinte aux droits et libertés constitutionnels"]'::jsonb, 3, 'Depuis 2010, le Conseil constitutionnel peut ainsi abroger une loi déjà appliquée.', 6),
    ('bcd9f51a-4283-5ae7-aa69-1f70abbeb990'::uuid, 'e48fca4d-46b5-5f65-ae83-02a3bd740b74'::uuid, 'Qui négocie les conventions collectives ?', 'mcq', '["Les partenaires sociaux","Le Parlement","Le Conseil d’État","Les juges prud’homaux"]'::jsonb, 0, 'Syndicats de salariés et organisations d’employeurs.', 7),
    ('02765eb7-1d7b-514d-86f6-a63278d6258b'::uuid, 'e48fca4d-46b5-5f65-ae83-02a3bd740b74'::uuid, 'Un décret est pris par…', 'mcq', '["Le Parlement","Un juge","Le Gouvernement (Premier ministre ou Président)","Les syndicats"]'::jsonb, 2, 'C’est un acte réglementaire, inférieur à la loi.', 8),
    ('66710112-1efb-5e99-9b3c-0d2527119b9f'::uuid, 'e48fca4d-46b5-5f65-ae83-02a3bd740b74'::uuid, 'Qu’appelle-t-on jurisprudence ?', 'mcq', '["Un texte voté par le Sénat","Un traité international","Le règlement d’une entreprise","L’ensemble des décisions rendues par les juges"]'::jsonb, 3, 'Elle interprète la loi et comble ses silences.', 9),
    ('3b3dd648-aa37-5d53-bf36-7089a4592e6b'::uuid, 'e48fca4d-46b5-5f65-ae83-02a3bd740b74'::uuid, 'Quelle institution européenne propose les textes ?', 'mcq', '["Le Parlement européen","La Cour de justice","La Commission européenne","La Banque centrale européenne"]'::jsonb, 2, 'La Commission a l’initiative ; le Parlement et le Conseil adoptent.', 10),
    ('aaae7821-3838-5104-a090-8dd598218b70'::uuid, 'e48fca4d-46b5-5f65-ae83-02a3bd740b74'::uuid, 'Un arrêté municipal contraire à une loi doit…', 'mcq', '["S’appliquer quand même, car il est plus récent","Être annulé, car il ne respecte pas une norme supérieure","Être soumis à référendum","Être validé par le préfet"]'::jsonb, 1, 'La norme inférieure doit respecter la norme supérieure.', 11),
    ('bbfad38c-a557-5fda-9e06-b7502073c081'::uuid, 'e48fca4d-46b5-5f65-ae83-02a3bd740b74'::uuid, 'Qui a théorisé la séparation des pouvoirs ?', 'mcq', '["Montesquieu","Rousseau","Voltaire","Napoléon"]'::jsonb, 0, 'Dans « De l’esprit des lois » (1748).', 12),
    ('6b9ff95d-e899-570c-9177-4fc96f9c221e'::uuid, '65a97559-8147-58a3-ab02-1169be9f002a'::uuid, 'Dans un procès civil, comment s’appelle celui qui engage l’action ?', 'mcq', '["Le défendeur","Le prévenu","Le demandeur","Le témoin"]'::jsonb, 2, 'Le défendeur est celui contre qui l’action est dirigée.', 1),
    ('7e1be2fb-ec12-544e-a9fc-43d84c18c323'::uuid, '65a97559-8147-58a3-ab02-1169be9f002a'::uuid, 'Un contrat de vente est…', 'mcq', '["Un acte juridique","Un fait juridique","Une présomption","Une prétention"]'::jsonb, 0, 'Il résulte d’une volonté de produire des effets de droit.', 2),
    ('992c435c-f1c2-5f88-9319-f9b95569c897'::uuid, '65a97559-8147-58a3-ab02-1169be9f002a'::uuid, 'Un accident de la circulation est un fait juridique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ses effets de droit (obligation de réparer) n’ont pas été voulus.', 3),
    ('22aa744b-838e-5fa1-ba31-27bc859ca50b'::uuid, '65a97559-8147-58a3-ab02-1169be9f002a'::uuid, 'Comment se prouve un fait juridique ?', 'mcq', '["Uniquement par acte notarié","Par tout moyen","Uniquement par l’aveu","Il ne se prouve pas"]'::jsonb, 1, 'Témoignages, photos, messages, constats… La preuve est libre.', 4),
    ('e30b90b3-0133-5166-b6d1-55fcf4a15681'::uuid, '65a97559-8147-58a3-ab02-1169be9f002a'::uuid, 'À partir de quel montant un acte juridique doit-il en principe être prouvé par écrit ?', 'mcq', '["500 euros","1 500 euros","1 000 euros","5 000 euros"]'::jsonb, 1, 'Au-delà de 1 500 euros, un écrit est exigé.', 5),
    ('581e1296-b060-5e46-8646-c2f5e152cb0f'::uuid, '65a97559-8147-58a3-ab02-1169be9f002a'::uuid, 'Sur qui pèse en principe la charge de la preuve ?', 'mcq', '["Sur le juge","Sur le défendeur","Sur l’avocat","Sur celui qui réclame l’exécution d’une obligation"]'::jsonb, 3, 'Article 1353 du Code civil.', 6),
    ('78560f42-9809-5b26-a3cd-2d3c730aa157'::uuid, '65a97559-8147-58a3-ab02-1169be9f002a'::uuid, 'Un acte authentique est rédigé…', 'mcq', '["Par un officier public, comme un notaire","Par les parties seules","Par un témoin","Par le juge après le procès"]'::jsonb, 0, 'Il a une force probante renforcée.', 7),
    ('5a1a2e9b-f7d5-53a5-8d77-45030641eab5'::uuid, '65a97559-8147-58a3-ab02-1169be9f002a'::uuid, 'L’écrit électronique a la même valeur que l’écrit papier si…', 'mcq', '["Il est imprimé","Il est envoyé par courriel","Son auteur est identifié et son intégrité garantie","Il est rédigé en majuscules"]'::jsonb, 2, 'D’où la signature électronique.', 8),
    ('0af206ba-4c78-5f83-8f7e-60738f566f33'::uuid, '65a97559-8147-58a3-ab02-1169be9f002a'::uuid, 'Une présomption irréfragable…', 'mcq', '["Peut être renversée par la preuve contraire","N’existe qu’en droit pénal","Est un témoignage","Ne peut pas être renversée"]'::jsonb, 3, 'À l’inverse, une présomption simple admet la preuve contraire.', 9),
    ('180e1f49-0738-500e-9fd7-9002e28447bd'::uuid, '65a97559-8147-58a3-ab02-1169be9f002a'::uuid, 'Qu’est-ce que l’aveu ?', 'mcq', '["Le jugement rendu par le tribunal","La plainte de la victime","La déclaration par laquelle une partie reconnaît un fait qui lui est défavorable","Le témoignage d’un tiers"]'::jsonb, 2, 'L’aveu judiciaire fait pleine foi contre son auteur.', 10),
    ('a14d5c31-91a5-57e4-9b89-b0713f545890'::uuid, '65a97559-8147-58a3-ab02-1169be9f002a'::uuid, 'En matière pénale, le juge se décide selon…', 'mcq', '["L’écrit exclusivement","Son intime conviction","Le montant du préjudice","L’avis des témoins uniquement"]'::jsonb, 1, 'La preuve y est libre, mais doit avoir été obtenue loyalement.', 11),
    ('fa809dd9-6f81-557f-84b5-292a28610ce9'::uuid, '65a97559-8147-58a3-ab02-1169be9f002a'::uuid, 'Un conflit devient un litige lorsque…', 'mcq', '["Il est formulé en termes juridiques par des prétentions","Il dure plus d’un an","Les parties s’insultent","La police intervient"]'::jsonb, 0, 'Une partie invoque une règle de droit à l’appui de sa demande.', 12),
    ('92157c60-224a-5252-a071-4d02078ebd26'::uuid, '3535d49c-d83b-5a9f-9e7d-d67d61e929e7'::uuid, 'Quelle juridiction juge un litige entre un salarié et son employeur ?', 'mcq', '["Le tribunal de commerce","Le tribunal correctionnel","Le conseil de prud’hommes","Le tribunal administratif"]'::jsonb, 2, 'C’est une question de compétence d’attribution.', 1),
    ('1b64f4f3-fb63-5c34-bcc1-6866f29ed704'::uuid, '3535d49c-d83b-5a9f-9e7d-d67d61e929e7'::uuid, 'Quelle juridiction juge les délits ?', 'mcq', '["Le tribunal correctionnel","Le tribunal de police","La cour d’assises","Le conseil de prud’hommes"]'::jsonb, 0, 'Le tribunal de police juge les contraventions, la cour d’assises les crimes.', 2),
    ('6345e3ee-74fb-5e7f-8d56-fb7050e3052d'::uuid, '3535d49c-d83b-5a9f-9e7d-d67d61e929e7'::uuid, 'La Cour de cassation rejuge les faits de l’affaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est juge du droit : elle vérifie seulement la bonne application des règles.', 3),
    ('a4c7de4b-18da-5a5e-8e71-784a48c63e71'::uuid, '3535d49c-d83b-5a9f-9e7d-d67d61e929e7'::uuid, 'Qu’est-ce que le double degré de juridiction ?', 'mcq', '["Le fait d’avoir deux juges par audience","Le droit de faire rejuger son affaire en fait et en droit par une cour d’appel","Le droit d’avoir deux avocats","La possibilité de saisir deux tribunaux en même temps"]'::jsonb, 1, 'L’appel en est la mise en œuvre.', 4),
    ('cb35fc53-2c71-5c59-b176-77aa5804933f'::uuid, '3535d49c-d83b-5a9f-9e7d-d67d61e929e7'::uuid, 'Comment appelle-t-on la décision d’une cour d’appel ?', 'mcq', '["Un jugement","Un arrêt","Une ordonnance pénale","Un décret"]'::jsonb, 1, 'On parle de jugement pour les tribunaux de premier degré.', 5),
    ('89fe661d-b286-5b12-bf3e-a21d68e44349'::uuid, '3535d49c-d83b-5a9f-9e7d-d67d61e929e7'::uuid, 'Quelle juridiction civile de droit commun a été créée en 2020 ?', 'mcq', '["Le tribunal d’instance","Le tribunal de grande instance","La cour d’assises","Le tribunal judiciaire"]'::jsonb, 3, 'Elle a fusionné le tribunal d’instance et le tribunal de grande instance.', 6),
    ('fc25d12b-f78c-51cb-9811-71cddc53a454'::uuid, '3535d49c-d83b-5a9f-9e7d-d67d61e929e7'::uuid, 'Que permet la constitution de partie civile ?', 'mcq', '["À la victime d’obtenir réparation dans le cadre du procès pénal","À l’accusé de choisir son juge","Au procureur de classer l’affaire","À un témoin d’être payé"]'::jsonb, 0, 'La victime demande des dommages et intérêts devant le juge pénal.', 7),
    ('7248c07c-e317-5304-9fcc-a402efa23fa4'::uuid, '3535d49c-d83b-5a9f-9e7d-d67d61e929e7'::uuid, 'Classe les infractions de la moins grave à la plus grave.', 'mcq', '["Délit, contravention, crime","Crime, délit, contravention","Contravention, délit, crime","Contravention, crime, délit"]'::jsonb, 2, 'Chacune relève d’une juridiction différente.', 8),
    ('72d5dfdc-c9cf-5042-a72d-54be7dda8e56'::uuid, '3535d49c-d83b-5a9f-9e7d-d67d61e929e7'::uuid, 'L’assignation est…', 'mcq', '["La décision finale du juge","La peine prononcée","Le recours devant la Cour de cassation","L’acte par lequel le demandeur informe le défendeur qu’il l’attaque en justice"]'::jsonb, 3, 'Elle est délivrée par un commissaire de justice et introduit l’instance.', 9),
    ('169673aa-15f3-5557-84c4-83a8af01b319'::uuid, '3535d49c-d83b-5a9f-9e7d-d67d61e929e7'::uuid, 'La présomption d’innocence signifie que…', 'mcq', '["Les mineurs ne peuvent jamais être condamnés","Le juge doit croire l’accusé","Toute personne poursuivie est considérée comme innocente tant que sa culpabilité n’est pas établie","Le procès est public"]'::jsonb, 2, 'C’est à l’accusation de prouver la culpabilité.', 10),
    ('f1a95f01-7597-54d9-a61f-a352e1d43f05'::uuid, '3535d49c-d83b-5a9f-9e7d-d67d61e929e7'::uuid, 'Où siège la Cour européenne des droits de l’homme ?', 'mcq', '["Bruxelles","Strasbourg","Luxembourg","La Haye"]'::jsonb, 1, 'On la saisit après avoir épuisé les recours internes.', 11),
    ('592ba62e-42c2-5498-be4c-b2d84254413b'::uuid, '3535d49c-d83b-5a9f-9e7d-d67d61e929e7'::uuid, 'Un litige entre un particulier et sa commune relève en principe…', 'mcq', '["Du tribunal administratif","Du tribunal judiciaire","Du conseil de prud’hommes","Du tribunal de commerce"]'::jsonb, 0, 'Les litiges avec l’administration relèvent de l’ordre administratif.', 12),
    ('1fc39336-9452-584b-9dbd-7634d3a5e5be'::uuid, '6dae7655-1cee-59f3-9b3d-3a72e04c94c1'::uuid, 'Quand commence la personnalité juridique d’une personne physique ?', 'mcq', '["À la conception, dans tous les cas","À la majorité","À la naissance, si l’enfant naît vivant et viable","À la déclaration en mairie"]'::jsonb, 2, 'L’enfant conçu peut toutefois recueillir des droits s’il naît vivant et viable.', 1),
    ('4c6217e3-1fb7-50bc-91e8-62aa364fc063'::uuid, '6dae7655-1cee-59f3-9b3d-3a72e04c94c1'::uuid, 'Laquelle de ces entités est une personne morale ?', 'mcq', '["Une société anonyme immatriculée","Un chien","Un groupe d’amis","Une famille"]'::jsonb, 0, 'La société immatriculée au registre a la personnalité morale.', 2),
    ('11d6aa4e-e746-50dc-af8d-8140487c2f43'::uuid, '6dae7655-1cee-59f3-9b3d-3a72e04c94c1'::uuid, 'Depuis 2015, l’animal est une personne juridique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un être vivant doué de sensibilité, soumis au régime des biens (art. 515-14 C. civ.).', 3),
    ('3f1a51d3-1218-5e3a-a549-8a04d9333dab'::uuid, '6dae7655-1cee-59f3-9b3d-3a72e04c94c1'::uuid, 'Quel est l’équivalent du domicile pour une personne morale ?', 'mcq', '["La dénomination","Le siège social","Le capital","L’objet social"]'::jsonb, 1, 'Le siège social détermine notamment le tribunal compétent.', 4),
    ('0bfff9c7-76d4-52c9-9d20-7a82c17e065e'::uuid, '6dae7655-1cee-59f3-9b3d-3a72e04c94c1'::uuid, 'Quand une association acquiert-elle la personnalité morale ?', 'mcq', '["Dès que deux personnes se réunissent","Après sa déclaration en préfecture","Après dix ans d’existence","Jamais"]'::jsonb, 1, 'Elle peut alors agir en justice, recevoir des cotisations, signer des contrats.', 5),
    ('a3574e6c-9e07-5218-a32f-0e06cca83a3b'::uuid, '6dae7655-1cee-59f3-9b3d-3a72e04c94c1'::uuid, 'Le droit à l’image est un droit…', 'mcq', '["Patrimonial","Réel","De créance","Extrapatrimonial"]'::jsonb, 3, 'Attaché à la personne, il n’est pas évaluable en argent en lui-même.', 6),
    ('1fbbf3ea-00b6-53c0-827c-b7be61d50dad'::uuid, '6dae7655-1cee-59f3-9b3d-3a72e04c94c1'::uuid, 'Un droit patrimonial est…', 'mcq', '["Évaluable en argent et transmissible","Attaché à la personne et intransmissible","Réservé aux personnes morales","Toujours gratuit"]'::jsonb, 0, 'La propriété ou une créance sont des droits patrimoniaux.', 7),
    ('c77965f8-38f7-58f4-94ff-35b95e2607af'::uuid, '6dae7655-1cee-59f3-9b3d-3a72e04c94c1'::uuid, 'Comment s’appelle le « nom » d’une société ?', 'mcq', '["Sa raison d’être","Son sigle obligatoire","Sa dénomination sociale","Son capital"]'::jsonb, 2, 'La dénomination identifie la personne morale.', 8),
    ('b1ad43ff-5a7c-5d03-ae57-3f3ea7ce14d0'::uuid, '6dae7655-1cee-59f3-9b3d-3a72e04c94c1'::uuid, 'Quand prend fin la personnalité juridique d’une personne physique ?', 'mcq', '["À la retraite","À la mise sous tutelle","À la faillite","Au décès"]'::jsonb, 3, 'La tutelle limite l’exercice des droits mais ne supprime pas la personnalité.', 9),
    ('6f22905a-ed62-59d9-907a-b309c369d164'::uuid, '6dae7655-1cee-59f3-9b3d-3a72e04c94c1'::uuid, 'Qui agit au nom d’une personne morale ?', 'mcq', '["Tous ses membres ensemble","Le préfet","Ses représentants légaux (gérant, président)","Le juge"]'::jsonb, 2, 'La personne morale agit par l’intermédiaire de ses organes.', 10),
    ('c5b5c9e3-8d89-5559-89ac-5822bc2d5013'::uuid, '6dae7655-1cee-59f3-9b3d-3a72e04c94c1'::uuid, 'Que permet la personnalité juridique ?', 'mcq', '["De voter aux élections uniquement","D’être titulaire de droits et d’obligations et d’agir en justice","De payer moins d’impôts","De ne pas avoir de dettes"]'::jsonb, 1, 'C’est l’aptitude à être sujet de droit.', 11),
    ('a88659eb-a62d-5a38-ae54-049df1bd3f27'::uuid, '6dae7655-1cee-59f3-9b3d-3a72e04c94c1'::uuid, 'Depuis 2022, une personne majeure peut, une fois dans sa vie…', 'mcq', '["Choisir de porter le nom de l’autre parent par déclaration en mairie","Changer de date de naissance","Renoncer à sa nationalité sans formalité","Supprimer son état civil"]'::jsonb, 0, 'La loi de 2022 a simplifié ce changement de nom d’usage et de nom de famille.', 12),
    ('859260a8-4ad9-5ef1-b0f7-5ae7f5d507ac'::uuid, 'fb74aa4b-7a4f-5239-8d63-7ef52902d37f'::uuid, 'La capacité de jouissance est…', 'mcq', '["L’aptitude à exercer seul ses droits","Le droit de vote","L’aptitude à être titulaire de droits","Le droit de propriété"]'::jsonb, 2, 'Toute personne l’a ; c’est l’exercice qui peut être limité.', 1),
    ('14184cd4-5aee-594b-9721-407a0ee6457c'::uuid, 'fb74aa4b-7a4f-5239-8d63-7ef52902d37f'::uuid, 'Un mineur non émancipé peut accomplir seul…', 'mcq', '["Les actes de la vie courante","La vente d’un appartement","Un emprunt immobilier","Une donation importante"]'::jsonb, 0, 'Acheter un repas ou un livre est un acte de la vie courante.', 2),
    ('53f52d45-c257-5852-8221-2d8951889a93'::uuid, 'fb74aa4b-7a4f-5239-8d63-7ef52902d37f'::uuid, 'Dans la tutelle, la personne protégée est…', 'mcq', '["Assistée par un curateur","Libre d’agir seule","Privée de sa personnalité juridique","Représentée par un tuteur"]'::jsonb, 3, 'La tutelle est la mesure la plus protectrice.', 3),
    ('5b47a19f-e48e-5c63-9b00-bfaad60bba32'::uuid, 'fb74aa4b-7a4f-5239-8d63-7ef52902d37f'::uuid, 'La curatelle est plus protectrice que la tutelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : en curatelle, la personne agit mais doit être assistée pour les actes importants.', 4),
    ('548bf818-1fbe-5762-9723-a620a6a9e67d'::uuid, 'fb74aa4b-7a4f-5239-8d63-7ef52902d37f'::uuid, 'Vendre une maison est un acte…', 'mcq', '["D’administration","De disposition","De la vie courante","Extrapatrimonial"]'::jsonb, 1, 'Il modifie durablement la composition du patrimoine.', 5),
    ('f633d45d-c747-5a29-bbc2-cf07667da92c'::uuid, 'fb74aa4b-7a4f-5239-8d63-7ef52902d37f'::uuid, 'Encaisser des loyers est un acte…', 'mcq', '["De disposition","Interdit au propriétaire","Pénal","D’administration"]'::jsonb, 3, 'C’est une gestion courante qui ne met pas le patrimoine en danger.', 6),
    ('c8260a21-7fac-544a-a2a9-ed5298e8a96c'::uuid, 'fb74aa4b-7a4f-5239-8d63-7ef52902d37f'::uuid, 'Qu’est-ce que le patrimoine ?', 'mcq', '["L’ensemble des droits et obligations d’une personne évaluables en argent","L’ensemble des biens immobiliers d’une personne","Le salaire annuel","L’ensemble des droits de la personnalité"]'::jsonb, 0, 'Il comprend un actif et un passif.', 7),
    ('0ea5ba31-9061-5c4c-ae4c-48fc0523f9f5'::uuid, 'fb74aa4b-7a4f-5239-8d63-7ef52902d37f'::uuid, 'À partir de quel âge un mineur peut-il être émancipé ?', 'mcq', '["14 ans","15 ans","16 ans","17 ans"]'::jsonb, 2, 'Il acquiert alors la capacité d’un majeur pour la plupart des actes.', 8),
    ('86943b9b-7e15-5367-bf66-0c28dde5484e'::uuid, 'fb74aa4b-7a4f-5239-8d63-7ef52902d37f'::uuid, 'Un mandat est une représentation…', 'mcq', '["Légale","Judiciaire","Pénale","Conventionnelle"]'::jsonb, 3, 'Elle naît d’un contrat entre le mandant et le mandataire.', 9),
    ('36b79b93-d785-57a7-990d-50e0a36efd68'::uuid, 'fb74aa4b-7a4f-5239-8d63-7ef52902d37f'::uuid, 'Pourquoi le droit prévoit-il des incapacités ?', 'mcq', '["Pour punir les personnes","Pour réduire les impôts","Pour protéger les personnes vulnérables","Pour éviter les procès"]'::jsonb, 2, 'L’incapacité est une mesure de protection, jamais une sanction.', 10),
    ('54e9f7f4-a581-5f14-8f40-dce12fe88f82'::uuid, 'fb74aa4b-7a4f-5239-8d63-7ef52902d37f'::uuid, 'Le droit à la vie privée fait partie du patrimoine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un droit extrapatrimonial, non évaluable en argent.', 11),
    ('5bed6c28-5981-5091-afad-6d76ff55f769'::uuid, 'fb74aa4b-7a4f-5239-8d63-7ef52902d37f'::uuid, 'Les créanciers d’une personne peuvent en principe…', 'mcq', '["Saisir ses biens pour se faire payer","Saisir ses droits extrapatrimoniaux","Changer son nom","Prendre sa place en justice sans jugement"]'::jsonb, 0, 'L’actif du patrimoine répond du passif.', 12),
    ('4925d68b-909c-5fc5-824e-44ea98f3b608'::uuid, 'b5588449-793f-58ee-97c8-624ef8f13fc6'::uuid, 'Quel article du Code civil protège la vie privée ?', 'mcq', '["Article 1240","Article 544","Article 9","Article 1103"]'::jsonb, 2, '« Chacun a droit au respect de sa vie privée. »', 1),
    ('ef3eabb4-ac2d-5b8e-9ae2-d67c2162cb87'::uuid, 'b5588449-793f-58ee-97c8-624ef8f13fc6'::uuid, 'Les droits de la personnalité sont…', 'mcq', '["Inaliénables, insaisissables et imprescriptibles","Cessibles et saisissables","Réservés aux personnes publiques","Transmissibles par héritage"]'::jsonb, 0, 'Ils sont attachés à la personne elle-même.', 2),
    ('470528fc-0116-5561-8985-b5bfbf21a798'::uuid, 'b5588449-793f-58ee-97c8-624ef8f13fc6'::uuid, 'Une adresse IP peut être une donnée à caractère personnel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle permet d’identifier indirectement une personne.', 3),
    ('4fea50cc-e407-5541-9ac5-fcf1576f0da6'::uuid, 'b5588449-793f-58ee-97c8-624ef8f13fc6'::uuid, 'Quel texte encadre le traitement des données personnelles dans l’Union européenne ?', 'mcq', '["La loi Macron","Le RGPD","Le Code pénal","Le traité de Maastricht"]'::jsonb, 1, 'Le règlement général sur la protection des données, applicable depuis 2018.', 4),
    ('ee53be39-0f8d-5407-9e91-84380df5c246'::uuid, 'b5588449-793f-58ee-97c8-624ef8f13fc6'::uuid, 'Quelle autorité française contrôle le respect du RGPD ?', 'mcq', '["L’Arcom","La CNIL","L’Autorité de la concurrence","La DGCCRF"]'::jsonb, 1, 'La Commission nationale de l’informatique et des libertés peut sanctionner.', 5),
    ('fbb88e8b-8632-5495-82db-c7cf022f43a9'::uuid, 'b5588449-793f-58ee-97c8-624ef8f13fc6'::uuid, 'À partir de quel âge un mineur peut-il consentir seul au traitement de ses données par un réseau social en France ?', 'mcq', '["13 ans","16 ans","18 ans","15 ans"]'::jsonb, 3, 'En dessous, l’accord des parents est nécessaire.', 6),
    ('95e1dc03-cf17-52fd-8736-35df9d9bc2cb'::uuid, 'b5588449-793f-58ee-97c8-624ef8f13fc6'::uuid, 'Le droit à l’image permet de s’opposer…', 'mcq', '["À la captation et à la diffusion de son image sans consentement","À toute photographie de foule","À la publication d’une œuvre d’art","À la vidéosurveillance publique dans tous les cas"]'::jsonb, 0, 'Des exceptions existent : actualité, foule, fonctions publiques.', 7),
    ('8d354337-eebb-58d9-834c-2bfcbaf4ba0f'::uuid, 'b5588449-793f-58ee-97c8-624ef8f13fc6'::uuid, 'Le principe de minimisation du RGPD impose de…', 'mcq', '["Collecter le plus de données possible","Supprimer toutes les données au bout d’un mois","Ne collecter que les données nécessaires à une finalité précise","Vendre les données à bas prix"]'::jsonb, 2, 'La finalité doit être déterminée à l’avance.', 8),
    ('144364f5-3aa3-5d8a-8154-9d45a24053bf'::uuid, 'b5588449-793f-58ee-97c8-624ef8f13fc6'::uuid, 'Comment se répare une atteinte à un droit extrapatrimonial ?', 'mcq', '["Elle ne peut pas être réparée","Par une peine de prison obligatoire","Par un changement de nom","Par des dommages et intérêts et des mesures pour faire cesser l’atteinte"]'::jsonb, 3, 'Le droit n’est pas évaluable en argent, mais son atteinte l’est.', 9),
    ('5543c8dc-6e75-536c-b893-8b09a5389376'::uuid, 'b5588449-793f-58ee-97c8-624ef8f13fc6'::uuid, 'Le droit à l’effacement est aussi appelé…', 'mcq', '["Droit de rétractation","Droit de réponse","Droit à l’oubli","Droit de retrait"]'::jsonb, 2, 'Il permet de demander la suppression de ses données.', 10),
    ('f55f35ce-3ceb-5edc-88a0-dafb56651138'::uuid, 'b5588449-793f-58ee-97c8-624ef8f13fc6'::uuid, 'L’historique de navigation et la géolocalisation font partie de l’identité numérique…', 'mcq', '["Formelle","Informelle","Juridique","Patrimoniale"]'::jsonb, 1, 'Ce sont des traces laissées sans les publier volontairement.', 11),
    ('e95b7cc7-01d6-5884-9f61-9ab4d7d6cded'::uuid, 'b5588449-793f-58ee-97c8-624ef8f13fc6'::uuid, 'Une personnalité publique a droit au respect de sa vie privée pour ce qui ne relève pas de son activité publique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sa notoriété ne supprime pas sa vie privée.', 12),
    ('1df1ba16-27b7-52e0-9f39-f4b7de57b737'::uuid, '55d1f463-225b-5582-8996-cf2871b99d2e'::uuid, 'Quel attribut du droit de propriété permet de vendre son bien ?', 'mcq', '["L’usus","Le fructus","L’abusus","Le monopole"]'::jsonb, 2, 'L’abusus est le droit de disposer : vendre, donner, détruire.', 1),
    ('4da66b5f-7474-56ee-bf82-0bbcb92e8db2'::uuid, '55d1f463-225b-5582-8996-cf2871b99d2e'::uuid, 'Percevoir les loyers d’un appartement correspond à…', 'mcq', '["Le fructus","L’usus","L’abusus","L’exclusivité"]'::jsonb, 0, 'Les loyers sont les fruits civils du bien.', 2),
    ('0be7f702-928b-5b06-b63c-4528be395cd8'::uuid, '55d1f463-225b-5582-8996-cf2871b99d2e'::uuid, 'Une marque est un bien…', 'mcq', '["Corporel meuble","Corporel immeuble","Extrapatrimonial","Incorporel"]'::jsonb, 3, 'Elle n’a pas d’existence matérielle.', 3),
    ('ece67d37-2dfa-5a49-bd05-3351a3c6fbda'::uuid, '55d1f463-225b-5582-8996-cf2871b99d2e'::uuid, 'Le droit de propriété se perd si l’on n’utilise pas son bien pendant dix ans.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est perpétuel : il ne s’éteint pas par le non-usage.', 4),
    ('7d4617b0-aade-5b71-a331-48d0c83dddde'::uuid, '55d1f463-225b-5582-8996-cf2871b99d2e'::uuid, 'Pour obtenir réparation d’un trouble anormal de voisinage, la victime doit…', 'mcq', '["Prouver une faute du voisin","Prouver que le trouble excède les inconvénients normaux du voisinage","Avoir porté plainte au pénal","Être propriétaire depuis vingt ans"]'::jsonb, 1, 'C’est une responsabilité sans faute.', 5),
    ('f5434715-d613-55a3-89c0-39e3b0329499'::uuid, '55d1f463-225b-5582-8996-cf2871b99d2e'::uuid, 'Quand une œuvre est-elle protégée par le droit d’auteur ?', 'mcq', '["Après dépôt à l’INPI","Après publication officielle","Après dix ans","Dès sa création, sans formalité"]'::jsonb, 3, 'Il suffit qu’elle soit originale.', 6),
    ('89fe8b8c-04f0-5aca-a584-84705dd25bd7'::uuid, '55d1f463-225b-5582-8996-cf2871b99d2e'::uuid, 'Combien de temps durent les droits patrimoniaux d’auteur après la mort de l’auteur ?', 'mcq', '["70 ans","20 ans","50 ans","Ils sont perpétuels"]'::jsonb, 0, 'Le droit moral, lui, est perpétuel.', 7),
    ('b791d57a-2ce1-53c6-b199-e4c7b8fe53db'::uuid, '55d1f463-225b-5582-8996-cf2871b99d2e'::uuid, 'Une marque déposée est protégée…', 'mcq', '["5 ans non renouvelables","20 ans","10 ans renouvelables indéfiniment","À vie"]'::jsonb, 2, 'Le dépôt se fait auprès de l’INPI.', 8),
    ('9d28544e-e20b-5fee-83ae-4b7271167537'::uuid, '55d1f463-225b-5582-8996-cf2871b99d2e'::uuid, 'Comment s’appelle l’atteinte à un droit de propriété intellectuelle ?', 'mcq', '["La concurrence déloyale","Le plagiat légal","L’expropriation","La contrefaçon"]'::jsonb, 3, 'Elle se sanctionne par l’action en contrefaçon.', 9),
    ('81e63dab-ce2c-5b35-af3a-57a2c8257da4'::uuid, '55d1f463-225b-5582-8996-cf2871b99d2e'::uuid, 'Le caractère exclusif du droit de propriété signifie que…', 'mcq', '["Le bien est unique au monde","Le bien ne peut pas être vendu","Le propriétaire peut interdire aux autres d’utiliser sa chose","Seul l’État peut être propriétaire"]'::jsonb, 2, 'Lui seul exerce les pouvoirs sur la chose.', 10),
    ('4cfb0b90-cd17-544f-8f1d-6571ddac27e3'::uuid, '55d1f463-225b-5582-8996-cf2871b99d2e'::uuid, 'Quel droit du créateur est perpétuel et inaliénable ?', 'mcq', '["Le droit de reproduction","Le droit moral","Le droit de représentation","Le droit de suite"]'::jsonb, 1, 'Paternité et respect de l’œuvre ne se vendent pas.', 11),
    ('e0354a97-aa0b-5595-81b2-7a155178b91a'::uuid, '55d1f463-225b-5582-8996-cf2871b99d2e'::uuid, 'L’expropriation pour cause d’utilité publique suppose…', 'mcq', '["Une juste et préalable indemnité","L’accord écrit du propriétaire","Une condamnation pénale","Une décision du maire seul"]'::jsonb, 0, 'C’est une limite au droit de propriété, strictement encadrée.', 12),
    ('3cc93489-a914-559e-abc2-def8d756fd99'::uuid, '1159db7d-4e94-5d9a-a4db-5bedced0d9d9'::uuid, 'Quelle est la fonction principale des ménages ?', 'mcq', '["Produire","Financer","Consommer","Redistribuer"]'::jsonb, 2, 'Ils consomment grâce à leurs revenus.', 1),
    ('2fda3fe8-2e03-5743-a760-274253af9afc'::uuid, '1159db7d-4e94-5d9a-a4db-5bedced0d9d9'::uuid, 'Quel agent produit des services non marchands et redistribue les revenus ?', 'mcq', '["Les administrations publiques","Les sociétés non financières","Les banques","Le reste du monde"]'::jsonb, 0, 'Elles sont financées par les prélèvements obligatoires.', 2),
    ('745b6296-46a3-5ce1-901e-9984bb5b0c3b'::uuid, '1159db7d-4e94-5d9a-a4db-5bedced0d9d9'::uuid, 'Qu’est-ce que le coût d’opportunité ?', 'mcq', '["Le prix affiché d’un bien","Le coût de production unitaire","Le montant des impôts","La valeur de la meilleure option à laquelle on renonce"]'::jsonb, 3, 'Tout choix implique un renoncement.', 3),
    ('bbde17cf-6de1-5f2f-94f8-482e6b27e333'::uuid, '1159db7d-4e94-5d9a-a4db-5bedced0d9d9'::uuid, 'L’utilité marginale est généralement…', 'mcq', '["Croissante","Décroissante","Constante","Négative dès la première unité"]'::jsonb, 1, 'Chaque unité supplémentaire satisfait un peu moins que la précédente.', 4),
    ('dfc836aa-329d-5776-899a-6e49d54dab52'::uuid, '1159db7d-4e94-5d9a-a4db-5bedced0d9d9'::uuid, 'Un producteur rationnel augmente sa production tant que…', 'mcq', '["Le coût marginal est supérieur à la recette marginale","La recette marginale est supérieure au coût marginal","Ses stocks augmentent","Ses concurrents produisent"]'::jsonb, 1, 'Il s’arrête quand Cm = Rm.', 5),
    ('321d161c-9ac5-58f4-b1cd-08f8455ccd82'::uuid, '1159db7d-4e94-5d9a-a4db-5bedced0d9d9'::uuid, 'Un service se caractérise par le fait qu’il…', 'mcq', '["Est stockable","Est toujours gratuit","Est produit par l’État","Est immatériel"]'::jsonb, 3, 'Il est en général produit et consommé en même temps.', 6),
    ('45d7103d-db8d-5aee-9f89-4a981ec5b293'::uuid, '1159db7d-4e94-5d9a-a4db-5bedced0d9d9'::uuid, 'Une école publique gratuite fournit une production…', 'mcq', '["Non marchande","Marchande","Financière","Illégale"]'::jsonb, 0, 'Elle est fournie gratuitement ou à un prix très inférieur au coût.', 7),
    ('b423ec85-55a9-59ed-84db-acc4b5052a16'::uuid, '1159db7d-4e94-5d9a-a4db-5bedced0d9d9'::uuid, 'Pourquoi l’eau est-elle bien moins chère que le diamant, alors qu’elle est plus utile ?', 'mcq', '["Parce qu’elle est taxée","Parce qu’elle est un service","Parce qu’elle est abondante","Parce que l’État la fabrique"]'::jsonb, 2, 'La valeur dépend de l’utilité ET de la rareté.', 8),
    ('96fbfcad-7eff-560e-a9b8-458eec97db5a'::uuid, '1159db7d-4e94-5d9a-a4db-5bedced0d9d9'::uuid, 'La contrainte budgétaire d’un ménage correspond à…', 'mcq', '["Son temps de loisir","Son lieu d’habitation","Ses préférences","Son revenu disponible"]'::jsonb, 3, 'On ne peut pas dépenser plus que ce dont on dispose (sauf à emprunter).', 9),
    ('e8c6e878-7f98-59bd-b1ab-822dd11d51d5'::uuid, '1159db7d-4e94-5d9a-a4db-5bedced0d9d9'::uuid, 'Une machine-outil achetée par une usine est un bien…', 'mcq', '["De consommation","Non marchand","De production","Incorporel"]'::jsonb, 2, 'Elle sert à produire d’autres biens.', 10),
    ('1a79447a-6668-5a35-a230-790be18c7f3a'::uuid, '1159db7d-4e94-5d9a-a4db-5bedced0d9d9'::uuid, 'Un agent rationnel est un agent qui…', 'mcq', '["Ne se trompe jamais","Cherche à atteindre au mieux ses objectifs compte tenu de ses contraintes","Dépense tout son revenu","Suit les conseils de l’État"]'::jsonb, 1, 'La rationalité porte sur la démarche, pas sur l’infaillibilité.', 11),
    ('4f788d25-1aca-5a1b-aa66-84402d34c773'::uuid, '1159db7d-4e94-5d9a-a4db-5bedced0d9d9'::uuid, 'Une tarte se vend 12 euros ; la suivante coûterait 15 euros à produire. Le producteur doit…', 'mcq', '["Ne pas la produire","Produire cette tarte supplémentaire","Baisser son prix à 0","Doubler sa production"]'::jsonb, 0, 'Cm (15) > Rm (12) : elle lui ferait perdre 3 euros.', 12),
    ('fbef95fd-ca5a-5444-9b7e-5432d6e443ca'::uuid, '7374d4e6-926a-58b1-912f-ef480cc8f606'::uuid, 'Sur quoi repose l’intérêt de la spécialisation ?', 'mcq', '["Sur le hasard","Sur la taille des entreprises","Sur la comparaison des coûts d’opportunité","Sur le niveau des impôts"]'::jsonb, 2, 'On se spécialise là où l’on renonce au moins pour produire.', 1),
    ('dab33086-8d9b-51ca-aa8b-eac2501a0b28'::uuid, '7374d4e6-926a-58b1-912f-ef480cc8f606'::uuid, 'Qui a développé la théorie des avantages comparatifs ?', 'mcq', '["David Ricardo","Adam Smith","Karl Marx","John Maynard Keynes"]'::jsonb, 0, 'Dans ses « Principes » de 1817.', 2),
    ('06af9a82-5341-5c05-9546-47924d9be53d'::uuid, '7374d4e6-926a-58b1-912f-ef480cc8f606'::uuid, 'Dans le circuit économique, le salaire versé par une entreprise à un ménage est un flux…', 'mcq', '["Réel","Financier international","Non marchand","Monétaire"]'::jsonb, 3, 'Il est la contrepartie du travail fourni, flux réel.', 3),
    ('4449f768-dd82-5bdf-81bd-594a036a607e'::uuid, '7374d4e6-926a-58b1-912f-ef480cc8f606'::uuid, 'Laquelle n’est PAS une fonction de la monnaie ?', 'mcq', '["Intermédiaire des échanges","Facteur de production","Unité de compte","Réserve de valeur"]'::jsonb, 1, 'Les trois fonctions sont : intermédiaire, unité de compte, réserve de valeur.', 4),
    ('fc4b1404-e638-5bd8-8e0e-2203b078645e'::uuid, '7374d4e6-926a-58b1-912f-ef480cc8f606'::uuid, 'Quel est le principal inconvénient du troc ?', 'mcq', '["Il est interdit par la loi","Il exige une double coïncidence des besoins","Il crée de l’inflation","Il suppose une banque"]'::jsonb, 1, 'Il faut trouver quelqu’un qui veut ce que j’ai et a ce que je veux.', 5),
    ('027cee15-cfd6-5bde-bacf-ef44179cf966'::uuid, '7374d4e6-926a-58b1-912f-ef480cc8f606'::uuid, 'Les dépôts sur les comptes bancaires constituent la monnaie…', 'mcq', '["Fiduciaire","Métallique","Marchandise","Scripturale"]'::jsonb, 3, 'Elle circule par carte, virement ou chèque et représente l’essentiel de la masse monétaire.', 6),
    ('08165266-62ca-54ed-85b0-80abee81a886'::uuid, '7374d4e6-926a-58b1-912f-ef480cc8f606'::uuid, 'Afficher le prix d’un vélo en euros illustre la fonction…', 'mcq', '["D’unité de compte","De réserve de valeur","D’intermédiaire des échanges","De crédit"]'::jsonb, 0, 'La monnaie mesure la valeur de tous les biens dans une même unité.', 7),
    ('4cdd29a6-b805-5a40-9f3b-2b313df75644'::uuid, '7374d4e6-926a-58b1-912f-ef480cc8f606'::uuid, 'Une plateforme de vente en ligne est un marché.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un marché peut être physique ou virtuel, dès lors qu’offre et demande s’y rencontrent.', 8),
    ('7c185821-1662-5c7e-bc75-c391ba262964'::uuid, '7374d4e6-926a-58b1-912f-ef480cc8f606'::uuid, 'Anna fait 10 pains ou 2 chaises par heure. Quel est le coût d’opportunité d’une chaise pour elle ?', 'mcq', '["2 pains","10 pains","0,2 pain","5 pains"]'::jsonb, 3, '10 ÷ 2 = 5 pains sacrifiés par chaise.', 9),
    ('786a8a14-3f6f-5738-98f6-b4fd63a15a24'::uuid, '7374d4e6-926a-58b1-912f-ef480cc8f606'::uuid, 'L’inflation affaiblit surtout la fonction de…', 'mcq', '["Unité de compte","Intermédiaire des échanges","Réserve de valeur","Création monétaire"]'::jsonb, 2, 'Si les prix montent, l’argent épargné permet d’acheter moins demain.', 10),
    ('00602ffc-6c6b-5e58-a2f8-ba1748a69d09'::uuid, '7374d4e6-926a-58b1-912f-ef480cc8f606'::uuid, 'Pourquoi le bitcoin remplit-il mal la fonction de réserve de valeur ?', 'mcq', '["Parce qu’il est imprimé par la BCE","Parce que sa valeur est très instable","Parce qu’il est illégal en France","Parce qu’il n’existe pas en ligne"]'::jsonb, 1, 'Sa valeur peut varier fortement en quelques jours.', 11),
    ('9eed2404-bfae-54e1-b4eb-3bac9d2fc1ed'::uuid, '7374d4e6-926a-58b1-912f-ef480cc8f606'::uuid, 'Une personne moins efficace dans toutes les productions n’a aucun intérêt à échanger.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle a intérêt à se spécialiser là où son désavantage est le plus faible : c’est tout l’apport de Ricardo.', 12),
    ('bdb73466-7628-55a2-8b66-2c6d6c00587f'::uuid, 'f86bdea7-5d11-5481-a6ba-5896c7e27a5b'::uuid, 'Qu’appelle-t-on capital humain ?', 'mcq', '["Le nombre de salariés d’une entreprise","La masse salariale","Les connaissances et compétences qui rendent un individu plus productif","Les machines utilisées par les salariés"]'::jsonb, 2, 'Il s’accumule par l’éducation, la formation et l’expérience.', 1),
    ('14e6ec85-b4be-5526-9189-b023838ce8aa'::uuid, 'f86bdea7-5d11-5481-a6ba-5896c7e27a5b'::uuid, 'Des matières premières transformées pendant la production constituent…', 'mcq', '["Du capital circulant","Du capital fixe","Du capital humain","Un investissement immatériel"]'::jsonb, 0, 'Elles sont détruites ou transformées dans la production.', 2),
    ('6b2fed39-6c1c-5887-8dec-1ba2155b17ad'::uuid, 'f86bdea7-5d11-5481-a6ba-5896c7e27a5b'::uuid, 'Des caisses automatiques qui remplacent des caissiers illustrent…', 'mcq', '["La complémentarité des facteurs","Le capital humain","La production non marchande","La substitution du capital au travail"]'::jsonb, 3, 'Le capital remplace le travail quand il devient relativement moins cher.', 3),
    ('fe25158e-68de-55af-b326-931f8d727259'::uuid, 'f86bdea7-5d11-5481-a6ba-5896c7e27a5b'::uuid, 'Comment calcule-t-on la productivité horaire du travail ?', 'mcq', '["Nombre d’heures ÷ production","Production ÷ nombre d’heures travaillées","Production × nombre de salariés","Chiffre d’affaires − salaires"]'::jsonb, 1, 'La productivité par tête divise par le nombre de travailleurs.', 4),
    ('7bc4b52c-d57b-51e1-9f32-59e87a7ca0b3'::uuid, 'f86bdea7-5d11-5481-a6ba-5896c7e27a5b'::uuid, 'Un atelier passe de 1 500 à 1 875 sacs par salarié. Le gain de productivité est de…', 'mcq', '["+ 20 %","+ 25 %","+ 37,5 %","+ 375 %"]'::jsonb, 1, '(1 875 − 1 500) ÷ 1 500 × 100 = 25 %.', 5),
    ('12e40c95-864c-53bc-a5b8-414c89fcf38f'::uuid, 'f86bdea7-5d11-5481-a6ba-5896c7e27a5b'::uuid, 'La productivité globale des facteurs reflète surtout…', 'mcq', '["Le nombre d’heures travaillées","Le montant des impôts","La quantité de monnaie","Le progrès technique et l’organisation"]'::jsonb, 3, 'C’est la part de la croissance non expliquée par la quantité de facteurs.', 6),
    ('92a30255-b52c-5bb5-ae67-c93553b6204c'::uuid, 'f86bdea7-5d11-5481-a6ba-5896c7e27a5b'::uuid, 'Un investissement de capacité vise à…', 'mcq', '["Augmenter les capacités de production","Remplacer une machine usée","Réduire les impôts","Rembourser une dette"]'::jsonb, 0, 'L’investissement de productivité, lui, vise à produire à moindre coût.', 7),
    ('fda0b6c0-bdea-5f73-ae5b-1113b7696edc'::uuid, 'f86bdea7-5d11-5481-a6ba-5896c7e27a5b'::uuid, 'Un camion et son chauffeur sont des facteurs complémentaires.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’un ne peut pas produire le service de transport sans l’autre.', 8),
    ('f3b3d9ef-0e67-5efb-b440-adf5639ebea5'::uuid, 'f86bdea7-5d11-5481-a6ba-5896c7e27a5b'::uuid, 'Laquelle de ces dépenses est un investissement immatériel ?', 'mcq', '["L’achat d’un bâtiment","L’achat de matières premières","Le paiement des salaires","Un programme de recherche"]'::jsonb, 3, 'Recherche, formation et logiciels sont des investissements immatériels.', 9),
    ('201c06ff-cf77-5187-8ae2-65f463eb66fd'::uuid, 'f86bdea7-5d11-5481-a6ba-5896c7e27a5b'::uuid, 'Les gains de productivité peuvent permettre…', 'mcq', '["Uniquement d’augmenter les impôts","De supprimer toute production","D’augmenter les salaires ou de baisser les prix","D’augmenter la durée du travail obligatoirement"]'::jsonb, 2, 'Ils se partagent entre salariés, entreprises, consommateurs et État.', 10),
    ('836a0729-1752-5cbd-8c74-4d291a20e508'::uuid, 'f86bdea7-5d11-5481-a6ba-5896c7e27a5b'::uuid, 'Une entreprise remplace du travail par du capital surtout quand…', 'mcq', '["Les machines deviennent plus chères","Le coût relatif du travail augmente","La demande baisse","Les salaires baissent"]'::jsonb, 1, 'Le choix de la combinaison dépend du coût relatif des facteurs.', 11),
    ('3617108b-3ce3-5004-89c6-d212504719c2'::uuid, 'f86bdea7-5d11-5481-a6ba-5896c7e27a5b'::uuid, 'Dans la production, le brevet obtenu après un programme de recherche est…', 'mcq', '["Un output","Un input","Un facteur primaire","Une consommation intermédiaire"]'::jsonb, 0, 'L’investissement en recherche est l’input, le brevet l’output.', 12),
    ('066fbf1f-6221-5c3c-a131-34ceec113f2d'::uuid, 'c04264fd-e7bb-5c27-b22c-ab3e8553f824'::uuid, 'Comment calcule-t-on la valeur ajoutée ?', 'mcq', '["Chiffre d’affaires − salaires","Bénéfice + impôts","Chiffre d’affaires − consommations intermédiaires","Production + importations"]'::jsonb, 2, 'On retire ce qui a été produit par d’autres.', 1),
    ('ce8cf69d-0165-504a-882b-5be198f59276'::uuid, 'c04264fd-e7bb-5c27-b22c-ab3e8553f824'::uuid, 'Pourquoi additionne-t-on les valeurs ajoutées et non les chiffres d’affaires ?', 'mcq', '["Pour éviter de compter plusieurs fois les consommations intermédiaires","Parce que les chiffres d’affaires sont secrets","Pour inclure les impôts","Pour exclure les services"]'::jsonb, 0, 'Le blé serait sinon compté chez l’agriculteur, le meunier et le boulanger.', 2),
    ('ab5c7cf8-2d93-5142-8130-9766cae39f3d'::uuid, 'c04264fd-e7bb-5c27-b22c-ab3e8553f824'::uuid, 'Une entreprise réalise 800 000 euros de chiffre d’affaires et 350 000 euros de consommations intermédiaires. Sa VA est de…', 'mcq', '["1 150 000 euros","350 000 euros","800 000 euros","450 000 euros"]'::jsonb, 3, '800 000 − 350 000 = 450 000 euros.', 3),
    ('e4d6b244-aee5-5af9-af88-8b90514c2294'::uuid, 'c04264fd-e7bb-5c27-b22c-ab3e8553f824'::uuid, 'Quel organisme calcule le PIB en France ?', 'mcq', '["La Banque de France","L’INSEE","Le FMI","Le Sénat"]'::jsonb, 1, 'L’Institut national de la statistique et des études économiques.', 4),
    ('bdcdc9c6-7e83-5e08-a4e7-0bb3f68cccde'::uuid, 'c04264fd-e7bb-5c27-b22c-ab3e8553f824'::uuid, 'Comment évalue-t-on la production non marchande dans le PIB ?', 'mcq', '["À zéro","À son coût de production","À son prix de vente","Elle n’est pas comptée"]'::jsonb, 1, 'Faute de prix, on retient ce qu’elle coûte.', 5),
    ('ed7ef9de-f079-57d0-b1d7-e644d4dc0e1b'::uuid, 'c04264fd-e7bb-5c27-b22c-ab3e8553f824'::uuid, 'Lequel de ces éléments n’entre PAS dans l’IDH ?', 'mcq', '["Le revenu par habitant","L’espérance de vie","Le niveau d’éducation","Les émissions de CO2"]'::jsonb, 3, 'L’IDH ne mesure pas l’état de l’environnement.', 6),
    ('4913ea77-60e7-5ef3-801a-c0d7215c32c5'::uuid, 'c04264fd-e7bb-5c27-b22c-ab3e8553f824'::uuid, 'Les dividendes sont des revenus…', 'mcq', '["Du capital","Du travail","Mixtes","De transfert"]'::jsonb, 0, 'Ils rémunèrent les actionnaires.', 7),
    ('67d76d93-9f1a-560c-96c7-e33883710a2f'::uuid, 'c04264fd-e7bb-5c27-b22c-ab3e8553f824'::uuid, 'Le revenu d’un artisan indépendant est un revenu mixte.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il rémunère à la fois son travail et le capital qu’il engage.', 8),
