    ('c70a5fe1-8035-50a8-b218-eaa4747aaa91'::uuid, 'fa80b67b-62e5-5b96-9c83-c4acaa7cafa2'::uuid, 'Le travail en groupe garantit à lui seul l’efficacité et la cohésion.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Tout dépend de la dynamique : leadership, cohésion, mode de décision.', 5),
    ('309d1260-c7e9-54be-8932-3a6327286856'::uuid, 'fa80b67b-62e5-5b96-9c83-c4acaa7cafa2'::uuid, 'Une communauté de pratiques est…', 'mcq', '["Un groupe de salariés qui partagent leur savoir-faire sur un métier","Un syndicat","Un comité de direction","Un fichier clients"]'::jsonb, 0, 'C’est un mode d’action coopératif.', 6),
    ('3d04fe55-4be4-5d29-807c-f7529dff19f8'::uuid, 'fa80b67b-62e5-5b96-9c83-c4acaa7cafa2'::uuid, 'L’intérêt du travail est un facteur de motivation…', 'mcq', '["Externe","Interne","Juridique","Financier"]'::jsonb, 1, 'Il vient de l’individu lui-même.', 7),
    ('105e7f94-696b-59ab-ad71-f00a9e7f7da6'::uuid, 'fa80b67b-62e5-5b96-9c83-c4acaa7cafa2'::uuid, 'Que recouvre la qualité de vie au travail ?', 'mcq', '["Uniquement le salaire","Conditions de travail, prévention des risques, hygiène, sécurité","Les dividendes","Le chiffre d’affaires"]'::jsonb, 1, 'C’est un déterminant du bien-être et de la performance.', 8),
