    ('77410c6d-7fa7-5cc7-b3e0-80e78f648055'::uuid, 'fa80b67b-62e5-5b96-9c83-c4acaa7cafa2'::uuid, 'Le remue-méninges (brainstorming) est une technique…', 'mcq', '["De créativité","Comptable","De recrutement","Juridique"]'::jsonb, 0, 'Elle favorise la production collective d’idées.', 10),
    ('f33b8522-33d0-505b-ba9d-f0b66aefb724'::uuid, 'fa80b67b-62e5-5b96-9c83-c4acaa7cafa2'::uuid, 'Les intérêts des salariés et des actionnaires peuvent diverger.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Salaires et dividendes se partagent la même valeur ajoutée.', 11),
    ('997d7568-0196-57c7-b3c1-2ed918f85d09'::uuid, 'fa80b67b-62e5-5b96-9c83-c4acaa7cafa2'::uuid, 'Un dirigeant qui recueille l’avis de ses équipes puis décide seul adopte un style…', 'mcq', '["Consultatif","Autoritaire","Participatif","Paternaliste"]'::jsonb, 0, 'Il consulte sans partager la décision.', 12),
    ('cf193024-1da1-52c3-83ac-ff9e38591512'::uuid, '8f48bd6d-ec50-5ef7-bf67-e66f3a0e72c3'::uuid, 'Quelle différence entre client et consommateur ?', 'mcq', '["Aucune","Le client achète, le consommateur utilise le produit","Le consommateur achète, le client utilise","Le client est toujours une entreprise"]'::jsonb, 1, 'Un parent (client) achète un jouet pour son enfant (consommateur).', 1),
    ('0533d074-22f3-57f2-a333-57b762570c32'::uuid, '8f48bd6d-ec50-5ef7-bf67-e66f3a0e72c3'::uuid, 'Quelle est l’étape du processus d’achat où l’on compare avis et prix ?', 'mcq', '["La prise de conscience du besoin","La recherche d’informations","Le comportement après l’achat","La livraison"]'::jsonb, 1, 'Comparateurs, avis et réseaux sociaux y jouent un rôle clé.', 2),
    ('477c4849-afd5-560c-8843-e66bc143bcf8'::uuid, '8f48bd6d-ec50-5ef7-bf67-e66f3a0e72c3'::uuid, 'La peur d’une arnaque sur un site inconnu est…', 'mcq', '["Une motivation","Un frein","Un besoin","Une attitude favorable"]'::jsonb, 1, 'Le frein retient l’achat.', 3),
