    ('972c7456-6d1d-5305-a003-abd7931fe185'::uuid, '915d224f-4c0d-5070-a7d1-7114a3486fff'::uuid, 'La démocratie participative dans une organisation consiste à…', 'mcq', '["Consulter et associer les membres aux décisions","Supprimer la direction","Voter les impôts","Imposer des décisions"]'::jsonb, 0, 'Budgets participatifs, consultations, gouvernance partagée.', 10),
