    ('06dd77a2-936b-5381-8f2d-ed8388715448'::uuid, 'e65591aa-8806-5bba-9a40-d336482ea143'::uuid, 'Dans une requête SQL, quel mot-clé filtre les lignes selon une condition ?', 'mcq', '["SELECT","FROM","WHERE","ORDER BY"]'::jsonb, 2, 'SELECT choisit les colonnes, FROM la table, WHERE la condition.', 4),
    ('4cad5e21-8e71-5ddb-a781-6becd9562060'::uuid, 'e65591aa-8806-5bba-9a40-d336482ea143'::uuid, 'À quoi sert ORDER BY ?', 'mcq', '["À trier le résultat","À supprimer des lignes","À créer une table","À chiffrer les données"]'::jsonb, 0, 'On trie selon une ou plusieurs colonnes.', 5),
    ('ff5c58f4-3f94-5338-b803-24460c82e9f5'::uuid, 'e65591aa-8806-5bba-9a40-d336482ea143'::uuid, 'Une jointure permet de…', 'mcq', '["Relier deux tables par une clé commune","Supprimer une base","Protéger un réseau","Créer une page web"]'::jsonb, 0, 'Par exemple CLIENT et COMMANDE par l’identifiant client.', 6),
    ('b57fd70b-c3ee-59a2-912f-446ff52067b2'::uuid, 'e65591aa-8806-5bba-9a40-d336482ea143'::uuid, 'Qu’est-ce qu’une API ?', 'mcq', '["Une interface qui permet à deux applications d’échanger des données","Un virus informatique","Un type d’écran","Une taxe numérique"]'::jsonb, 0, 'Interface de programmation applicative.', 7),
    ('22083e33-ab45-5438-a785-a579175b681a'::uuid, 'e65591aa-8806-5bba-9a40-d336482ea143'::uuid, 'Qu’est-ce que la recette d’un projet SI ?', 'mcq', '["Vérifier que le système livré répond au besoin exprimé","Le chiffre d’affaires du projet","La liste des ingrédients","Le budget prévisionnel"]'::jsonb, 0, 'On teste avant de déployer.', 8),
    ('6a5d7af3-0819-5ca6-8505-938cdd323ef5'::uuid, 'e65591aa-8806-5bba-9a40-d336482ea143'::uuid, 'HTML est un langage…', 'mcq', '["De balisage pour les pages web","De requête pour les bases de données","Comptable","De chiffrement"]'::jsonb, 0, 'XML et JSON servent aussi aux fichiers d’échange.', 9),
    ('4eac4356-7a27-508d-bab1-b0d5d0be30c7'::uuid, 'e65591aa-8806-5bba-9a40-d336482ea143'::uuid, 'Le protocole HTTPS garantit une communication chiffrée entre le navigateur et le site.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le S signifie sécurisé.', 10),
    ('0076fa4d-3660-5d70-bfd7-7f868f6e9092'::uuid, 'e65591aa-8806-5bba-9a40-d336482ea143'::uuid, 'Le numérique n’a aucun impact environnemental.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Centres de données et déchets électroniques pèsent sur l’environnement.', 11),
    ('87cf4a91-586f-504d-91dd-148cba29c207'::uuid, 'e65591aa-8806-5bba-9a40-d336482ea143'::uuid, 'Une URL sert à…', 'mcq', '["Adresser une ressource sur le réseau","Chiffrer un fichier","Calculer un coût","Trier une table"]'::jsonb, 0, 'C’est l’adresse d’une ressource sur le web.', 12),
    ('247781c0-9ce6-5b4c-b397-85087ee7cb44'::uuid, '0f1737e5-af7d-5a51-acfc-b2c36274b432'::uuid, 'Sur quelle partie du programme porte l’écrit de 4 heures ?', 'mcq', '["Sur l’enseignement spécifique choisi","Sur l’enseignement commun de terminale, avec les notions de 1re mobilisables","Uniquement sur le programme de 1re","Sur le droit et l’économie"]'::jsonb, 1, 'L’enseignement spécifique nourrit le projet et le Grand oral.', 1),
    ('05c4b81f-e5df-5a8b-ba40-e7118f5e6432'::uuid, '0f1737e5-af7d-5a51-acfc-b2c36274b432'::uuid, 'Combien de points l’écrit réserve-t-il à l’orthographe et à la syntaxe ?', 'mcq', '["0","2","4","10"]'::jsonb, 1, 'Deux points sur vingt, et la qualité de l’expression compte dans toute la copie.', 2),
    ('c039d621-f97b-5c3e-9b1e-08eed9f68c72'::uuid, '0f1737e5-af7d-5a51-acfc-b2c36274b432'::uuid, 'Comment se présente le sujet de l’écrit ?', 'mcq', '["Une dissertation libre","Plusieurs dossiers de documents sur des organisations réelles, avec des questions","Un QCM","Un exposé oral"]'::jsonb, 1, 'On analyse des situations réelles à partir de documents.', 3),
    ('4dc79837-0d11-55a6-842f-e9e4a368a7a2'::uuid, '0f1737e5-af7d-5a51-acfc-b2c36274b432'::uuid, 'Que faut-il ajouter à un calcul juste pour obtenir tous les points ?', 'mcq', '["Une interprétation de ce que le résultat signifie pour l’organisation","Un dessin","Une citation de philosophe","Rien"]'::jsonb, 0, 'Le calcul est un outil au service de l’analyse.', 4),
    ('c7c26564-e0a3-5707-a7f4-43635e07cbb1'::uuid, '0f1737e5-af7d-5a51-acfc-b2c36274b432'::uuid, 'Quelle est la structure d’une bonne réponse ?', 'mcq', '["Notion définie, application au cas avec un indice, conclusion","Une opinion personnelle","Une copie du document","Une liste de mots-clés"]'::jsonb, 0, 'Notion sans cas : hors sujet ; cas sans notion : paraphrase.', 5),
    ('a8ba244f-b571-5db8-bcfd-2016c9e5a9da'::uuid, '0f1737e5-af7d-5a51-acfc-b2c36274b432'::uuid, 'Quelle est la durée du Grand oral de la voie technologique ?', 'mcq', '["10 minutes","20 minutes","45 minutes","1 heure"]'::jsonb, 1, 'Avec 20 minutes de préparation et un coefficient 12.', 6),
    ('de5583ff-fd95-500b-9577-1e92ab6cfcf8'::uuid, '0f1737e5-af7d-5a51-acfc-b2c36274b432'::uuid, 'Au Grand oral, les questions présentées s’appuient sur…', 'mcq', '["L’étude approfondie (le projet) menée dans la spécialité","Un sujet tiré au sort sans lien avec l’année","Le programme de français","Uniquement l’actualité"]'::jsonb, 0, 'Elles sont préparées avec le professeur de la spécialité.', 7),
    ('d45b7f71-d4f2-54f3-8bde-c43bbbf9b717'::uuid, '0f1737e5-af7d-5a51-acfc-b2c36274b432'::uuid, 'L’enseignement spécifique est évalué à l’écrit de 4 heures.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’écrit porte sur l’enseignement commun ; le spécifique nourrit le projet.', 8),
    ('9d9290be-be08-5a0a-ada1-a1cd3aac44b0'::uuid, '0f1737e5-af7d-5a51-acfc-b2c36274b432'::uuid, 'Combien de temps de préparation pour l’oral de contrôle de la spécialité ?', 'mcq', '["10 minutes","40 minutes","2 heures","Aucun"]'::jsonb, 1, '40 minutes de préparation, 20 minutes d’épreuve.', 9),
    ('02a00280-1e49-5ab4-881a-ea62fce82c59'::uuid, '0f1737e5-af7d-5a51-acfc-b2c36274b432'::uuid, 'Pourquoi lire toutes les questions avant les documents ?', 'mcq', '["Pour lire les documents de façon active en sachant quoi chercher","Parce que les documents sont facultatifs","Pour gagner des points de présentation","Pour éviter de conclure"]'::jsonb, 0, 'On repère les indices utiles dès la première lecture.', 10),
    ('2067e739-fbda-5e59-8ff0-e35ed0f0c5bf'::uuid, '0f1737e5-af7d-5a51-acfc-b2c36274b432'::uuid, 'Une question de réflexion appelle…', 'mcq', '["Une réponse structurée : introduction, arguments, conclusion","Un seul mot","Un calcul uniquement","Un schéma sans texte"]'::jsonb, 0, 'Elle mobilise le cours et les exemples tirés des documents.', 11),
    ('0acf3bf8-b3bf-581a-983e-1f5f5375ba61'::uuid, '0f1737e5-af7d-5a51-acfc-b2c36274b432'::uuid, 'Montrer l’intérêt et les limites d’un outil de gestion fait partie des compétences évaluées.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La note de service le cite parmi les objectifs de l’épreuve.', 12),
    ('f684fd86-982f-573d-b04f-da7d8498b066'::uuid, '63cffa7b-f90e-5177-95c8-40e7bb1212fa'::uuid, 'Qu’est-ce que la structure de propriété d’une organisation ?', 'mcq', '["Son chiffre d’affaires","La répartition des bureaux","Qui détient l’organisation","Son organigramme hiérarchique"]'::jsonb, 2, 'Entrepreneur, associés, actionnaires, État ou adhérents : la propriété dit à qui appartient l’organisation.', 1),
    ('66f46a25-25b5-5b6e-a7af-e06c469c2757'::uuid, '63cffa7b-f90e-5177-95c8-40e7bb1212fa'::uuid, 'Que désigne le gouvernement (gouvernance) d’une organisation ?', 'mcq', '["L’ensemble des règles qui organisent le pouvoir de décision et son contrôle","Sa stratégie commerciale","Sa comptabilité","Les ministres qui la contrôlent"]'::jsonb, 0, 'Qui décide, comment et sous quel contrôle : c’est la gouvernance.', 2),
    ('b2df5325-d26b-5c6f-86a3-e675e7c59615'::uuid, '63cffa7b-f90e-5177-95c8-40e7bb1212fa'::uuid, 'Dans une association, qui élit le bureau ?', 'mcq', '["Le maire","Les donateurs","Les salariés","L’assemblée générale des adhérents"]'::jsonb, 3, 'Les adhérents réunis en assemblée générale élisent leurs responsables.', 3),
    ('41e25d7d-b6d3-58ed-ae0b-33455412dfbf'::uuid, '63cffa7b-f90e-5177-95c8-40e7bb1212fa'::uuid, 'Pourquoi le contrôle des dirigeants est-il un enjeu quand propriétaires et dirigeants sont différents ?', 'mcq', '["Parce qu’il n’y a plus de clients","Parce que leurs intérêts peuvent diverger","Parce que les dirigeants n’ont pas de salaire","Parce que la loi interdit les actionnaires"]'::jsonb, 1, 'Le dirigeant peut poursuivre ses propres buts (croissance, prestige) plutôt que ceux des propriétaires.', 4),
    ('2f32f7d5-752a-5d9e-aad6-eb69b696126f'::uuid, '63cffa7b-f90e-5177-95c8-40e7bb1212fa'::uuid, 'Quel acteur certifie la sincérité des comptes d’une société ?', 'mcq', '["Le client principal","Le directeur marketing","Le commissaire aux comptes","Le délégué syndical"]'::jsonb, 2, 'C’est un professionnel indépendant qui contrôle les comptes.', 5),
    ('6602d706-1737-5fd7-8f34-278fcca63546'::uuid, '63cffa7b-f90e-5177-95c8-40e7bb1212fa'::uuid, 'Dans une coopérative, chaque membre dispose d’un nombre de voix proportionnel à son apport.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le principe coopératif est « une personne, une voix », quel que soit l’apport.', 6),
    ('c5db65b9-10a0-5819-85a8-4b654ab7e7b1'::uuid, '63cffa7b-f90e-5177-95c8-40e7bb1212fa'::uuid, 'Quel est le but principal d’une entreprise privée ?', 'mcq', '["Réaliser un profit en vendant des biens et services","Servir ses adhérents sans vendre","Collecter l’impôt","Rendre un service d’intérêt général"]'::jsonb, 0, 'Elle produit pour le marché et cherche un bénéfice.', 7),
    ('a8cd97d3-59a6-5c5c-9d7c-22186876b477'::uuid, '63cffa7b-f90e-5177-95c8-40e7bb1212fa'::uuid, 'Dans une société anonyme, qui nomme la direction générale ?', 'mcq', '["Le comité social et économique","Les fournisseurs","Les clients","Le conseil d’administration élu par les actionnaires"]'::jsonb, 3, 'Les actionnaires élisent le conseil, qui nomme et contrôle la direction.', 8),
    ('ddd29f54-500a-514d-8e2c-e5b902cf8d30'::uuid, '63cffa7b-f90e-5177-95c8-40e7bb1212fa'::uuid, 'Quel organe peut révoquer les dirigeants d’une société ?', 'mcq', '["La médecine du travail","L’assemblée générale des actionnaires","Le service comptable","Le fournisseur principal"]'::jsonb, 1, 'L’assemblée générale approuve les comptes et peut changer les dirigeants.', 9),
    ('316ce009-90fc-52fe-9ef5-ecb583676317'::uuid, '63cffa7b-f90e-5177-95c8-40e7bb1212fa'::uuid, 'Dans une petite entreprise individuelle, le propriétaire est souvent aussi le dirigeant.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il n’y a alors pas de séparation entre propriété et pouvoir, donc peu de problème de contrôle.', 10),
    ('83cf7b91-b9dc-584b-855f-057471505f8c'::uuid, '63cffa7b-f90e-5177-95c8-40e7bb1212fa'::uuid, 'Qui contrôle notamment la gestion des organisations publiques ?', 'mcq', '["Les concurrents","Les actionnaires","La Cour des comptes et les élus","Les banques"]'::jsonb, 2, 'L’argent public est contrôlé par les élus et par les juridictions financières.', 11),
    ('4a840f0c-ff10-5d2b-a4c2-75dbe28bad13'::uuid, '63cffa7b-f90e-5177-95c8-40e7bb1212fa'::uuid, 'Une mutuelle est une organisation…', 'mcq', '["À but non lucratif, appartenant à ses sociétaires","Publique dirigée par un ministre","Individuelle","À but lucratif cotée en Bourse"]'::jsonb, 0, 'Les sociétaires en sont les propriétaires et élisent leurs représentants.', 12),
    ('d38a8a92-276e-5d68-8901-962d631ce821'::uuid, 'fa67c60e-4608-5b60-b881-f7504209b320'::uuid, 'Qu’est-ce qu’une attitude ?', 'mcq', '["Un diplôme","Une réaction physique brève","Une action observable","Une disposition favorable ou défavorable envers quelque chose"]'::jsonb, 3, 'L’attitude ne se voit pas directement : on la déduit des comportements.', 1),
    ('b44f4b79-1adb-5882-b47a-4cda2cd6cd72'::uuid, 'fa67c60e-4608-5b60-b881-f7504209b320'::uuid, 'Quelle notion désigne ce que l’individu fait et qu’on peut observer ?', 'mcq', '["La perception","Le comportement","L’émotion","La personnalité"]'::jsonb, 1, 'Le comportement est observable ; perceptions et attitudes se déduisent.', 2),
    ('9da534e1-3996-5553-98a8-96f0ea8ee776'::uuid, 'fa67c60e-4608-5b60-b881-f7504209b320'::uuid, 'Deux salariés sortent de la même réunion avec des avis opposés. Quelle notion l’explique ?', 'mcq', '["Le code","Le canal","La perception","La compétence"]'::jsonb, 2, 'Chacun sélectionne et interprète l’information à sa façon.', 3),
    ('e7865e4b-a1b7-5f6a-ba5a-ec53d9934ff3'::uuid, 'fa67c60e-4608-5b60-b881-f7504209b320'::uuid, 'Qu’est-ce que l’identité numérique ?', 'mcq', '["L’ensemble des traces qu’une personne laisse en ligne","Le mot de passe de sa messagerie","Sa carte d’identité scannée","Le numéro de sécurité sociale"]'::jsonb, 0, 'Profils, publications et ce que les autres publient sur toi la composent.', 4),
    ('af33c62a-b63f-56c6-a09d-5296d5f4229f'::uuid, 'fa67c60e-4608-5b60-b881-f7504209b320'::uuid, 'Quelle est une bonne pratique de gestion de l’identité numérique ?', 'mcq', '["Utiliser le même mot de passe partout","Ne jamais vérifier ce qu’on trouve sur soi","Tout publier en public","Paramétrer la confidentialité de ses comptes"]'::jsonb, 3, 'On maîtrise ainsi qui voit quoi.', 5),
    ('7d2d3543-f104-593b-8014-7c771cd29d1d'::uuid, 'fa67c60e-4608-5b60-b881-f7504209b320'::uuid, 'Dans le schéma de la communication, le « canal » désigne…', 'mcq', '["Le contenu du message","Le moyen de transmission","La personne qui reçoit","La langue utilisée"]'::jsonb, 1, 'Oral, écrit, messagerie, visioconférence sont des canaux.', 6),
    ('799a8804-491b-599b-be81-c9214e84e4c9'::uuid, 'fa67c60e-4608-5b60-b881-f7504209b320'::uuid, 'La rétroaction (feedback) permet…', 'mcq', '["De brouiller le message","De couper la communication","Au récepteur de montrer qu’il a compris","De choisir la langue"]'::jsonb, 2, 'Elle permet à l’émetteur de vérifier la réception et d’ajuster.', 7),
    ('34b3d536-365e-5885-974c-343c78ba241c'::uuid, 'fa67c60e-4608-5b60-b881-f7504209b320'::uuid, 'Le jargon technique employé devant un client non spécialiste constitue…', 'mcq', '["Un bruit","Une rétroaction","Un canal","Un contexte favorable"]'::jsonb, 0, 'Tout ce qui gêne la compréhension est un bruit, même s’il n’est pas sonore.', 8),
    ('c015f049-f444-5333-a174-616774e1d6ad'::uuid, 'fa67c60e-4608-5b60-b881-f7504209b320'::uuid, 'La communication non verbale n’a aucune influence sur le message.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ton, gestes et regard peuvent renforcer ou contredire les mots.', 9),
    ('9b00c86f-9a40-57c2-8d91-0448c64a8c2a'::uuid, 'fa67c60e-4608-5b60-b881-f7504209b320'::uuid, 'Les compétences regroupent…', 'mcq', '["Uniquement l’ancienneté","Le salaire et les primes","Uniquement les diplômes","Savoirs, savoir-faire et savoir-être mobilisés en situation"]'::jsonb, 3, 'La compétence se prouve en situation de travail.', 10),
    ('5374a283-3831-58d3-adc0-f07623dc8776'::uuid, 'fa67c60e-4608-5b60-b881-f7504209b320'::uuid, 'Rester calme face à un client agressif relève…', 'mcq', '["De l’identité numérique","Du contrôle de soi","De la perception","Du code"]'::jsonb, 1, 'C’est la capacité à maîtriser ses réactions émotionnelles.', 11),
    ('5fb34509-f964-54bf-b998-b73193980e8b'::uuid, 'fa67c60e-4608-5b60-b881-f7504209b320'::uuid, 'Un recruteur peut consulter l’identité numérique d’un candidat.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est fréquent : d’où l’intérêt de soigner son profil professionnel.', 12),
    ('daa9e3b3-1e0f-5972-b64f-dbfb10b6576c'::uuid, '3b23839d-6fcb-5bd0-907d-b4be8b3f4b5b'::uuid, 'Un groupe de référence est…', 'mcq', '["Un fichier de clients","Le groupe dont on fait partie","Un groupe auquel on se compare ou dont on adopte les normes","Le comité de direction"]'::jsonb, 2, 'On peut s’identifier à un groupe sans en être membre.', 1),
    ('4754bacf-7831-5359-8b25-c338586f5b20'::uuid, '3b23839d-6fcb-5bd0-907d-b4be8b3f4b5b'::uuid, 'Qu’est-ce que la culture d’organisation ?', 'mcq', '["L’ensemble des valeurs, normes, rites et symboles partagés","Le budget formation","La bibliothèque de l’entreprise","Le niveau de diplôme des salariés"]'::jsonb, 0, 'Elle donne une identité commune et guide les comportements.', 2),
    ('ffe2b766-046b-5877-9e8e-f85068e289b9'::uuid, '3b23839d-6fcb-5bd0-907d-b4be8b3f4b5b'::uuid, 'Le petit-déjeuner d’équipe chaque lundi est…', 'mcq', '["Une incitation financière","Une relation formelle","Une norme juridique","Un rituel"]'::jsonb, 3, 'Une pratique répétée qui renforce le sentiment d’appartenance.', 3),
    ('0b045bf5-6fe2-5f99-bd12-c6d2308ee343'::uuid, '3b23839d-6fcb-5bd0-907d-b4be8b3f4b5b'::uuid, 'Quelle relation est formelle ?', 'mcq', '["Deux collègues qui déjeunent ensemble","Un salarié qui rend compte à son supérieur hiérarchique","Un groupe d’amis au travail","L’entraide spontanée"]'::jsonb, 1, 'Elle est prévue par l’organigramme.', 4),
    ('40bd6a07-f252-533c-abb6-c6610c23e2bb'::uuid, '3b23839d-6fcb-5bd0-907d-b4be8b3f4b5b'::uuid, 'Le leadership peut exister sans position hiérarchique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un collègue respecté peut entraîner les autres sans être chef.', 5),
    ('c352b4d1-5456-5d45-8917-80ebf513d7ea'::uuid, '3b23839d-6fcb-5bd0-907d-b4be8b3f4b5b'::uuid, 'L’autorité se définit comme…', 'mcq', '["Le salaire le plus élevé","L’ancienneté seule","Un pouvoir légitime de donner des ordres, reconnu par ceux qui obéissent","La force physique"]'::jsonb, 2, 'Sans reconnaissance, l’autorité se réduit à de la contrainte.', 6),
    ('6d1e5ea9-2bb1-582d-ae2d-c7fee3aff6eb'::uuid, '3b23839d-6fcb-5bd0-907d-b4be8b3f4b5b'::uuid, 'Une prime sur objectifs est…', 'mcq', '["Une incitation","Un stéréotype","Un rituel","Une relation informelle"]'::jsonb, 0, 'L’incitation est le levier que l’organisation actionne pour stimuler la motivation.', 7),
    ('61ac7ec2-016f-52d1-906f-7896cb03ca02'::uuid, '3b23839d-6fcb-5bd0-907d-b4be8b3f4b5b'::uuid, '« Les commerciaux ne pensent qu’aux primes » est un exemple de…', 'mcq', '["Fiche de poste","Leadership","Norme","Stéréotype"]'::jsonb, 3, 'Une image simplifiée et généralisée d’un groupe, qui peut nuire aux relations.', 8),
    ('2f77337a-efc2-5231-bd16-3396d41e1b4e'::uuid, '3b23839d-6fcb-5bd0-907d-b4be8b3f4b5b'::uuid, 'Que décrit la fiche de poste ?', 'mcq', '["Le règlement de la cantine","Les missions et responsabilités d’un emploi","Les amitiés dans l’équipe","Le cours de l’action"]'::jsonb, 1, 'Elle situe l’individu dans l’organisation formelle.', 9),
    ('e9496b35-c664-5947-a054-8ce532577be5'::uuid, '3b23839d-6fcb-5bd0-907d-b4be8b3f4b5b'::uuid, 'Un réseau social d’entreprise est…', 'mcq', '["Un site de vente en ligne","Un fichier de paie","Un espace numérique d’échange interne","Un syndicat"]'::jsonb, 2, 'Il facilite le partage d’informations et les relations entre salariés.', 10),
    ('a88bc75f-cb2e-5fc9-a84a-ccec77c23ce4'::uuid, '3b23839d-6fcb-5bd0-907d-b4be8b3f4b5b'::uuid, 'Les conflits dans une organisation sont toujours à éviter car ils n’apportent rien.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Bien gérés, ils révèlent des problèmes et peuvent déboucher sur de meilleures solutions.', 11),
    ('76fe22be-8cca-51ae-a5f0-f3b267743f9f'::uuid, '3b23839d-6fcb-5bd0-907d-b4be8b3f4b5b'::uuid, 'Le statut d’un individu dans un groupe désigne…', 'mcq', '["Sa position dans le groupe","Son salaire","Son âge","Son adresse"]'::jsonb, 0, 'Le rôle est le comportement attendu de lui dans cette position.', 12),
    ('b69c7ae3-b708-5a12-943e-fdc4d55a0de2'::uuid, '28eba4b8-caa3-56a7-a1f7-59d5e7215c22'::uuid, 'Quelle différence entre qualification et compétence ?', 'mcq', '["La compétence est toujours un diplôme","La qualification ne concerne que les cadres","Aucune, ce sont des synonymes","La qualification atteste ce qu’on peut faire (diplôme), la compétence ce qu’on sait faire en situation"]'::jsonb, 3, 'La compétence se prouve dans le travail ; la qualification est attestée et rattachée au poste.', 1),
    ('dd1b4b32-556e-58dc-b9c5-de70f094aaee'::uuid, '28eba4b8-caa3-56a7-a1f7-59d5e7215c22'::uuid, 'Un salaire brut de 2 000 € avec 22 % de cotisations salariales donne un net d’environ…', 'mcq', '["1 560 €","1 780 €","2 440 €","440 €"]'::jsonb, 0, '2 000 × (1 − 0,22) = 1 560 €.', 2),
    ('e66378ec-33b3-57fc-bc4d-80f88ea6f06b'::uuid, '28eba4b8-caa3-56a7-a1f7-59d5e7215c22'::uuid, 'Le coût du travail pour l’employeur correspond à…', 'mcq', '["Le salaire brut moins les primes","Le salaire net","Le salaire brut plus les cotisations patronales et autres charges","Les cotisations salariales seules"]'::jsonb, 2, 'L’employeur paie le brut et, en plus, les cotisations patronales.', 3),
    ('0e7cc220-2694-53f1-a07c-a4c4742785fc'::uuid, '28eba4b8-caa3-56a7-a1f7-59d5e7215c22'::uuid, 'Comment calcule-t-on la productivité du travail ?', 'mcq', '["Production ÷ quantité de travail","Salaire ÷ production","Effectif × heures","Chiffre d’affaires − charges"]'::jsonb, 0, 'Elle mesure ce que produit une heure ou un salarié.', 4),
    ('d1475c37-dc74-57f6-8ed3-66a5a3585a90'::uuid, '28eba4b8-caa3-56a7-a1f7-59d5e7215c22'::uuid, '8 000 heures d’absence pour 160 000 heures théoriques : taux d’absentéisme ?', 'mcq', '["2 %","5 %","8 %","20 %"]'::jsonb, 1, '8 000 ÷ 160 000 × 100 = 5 %.', 5),
    ('2e383aa7-642e-5054-b153-e7ad7d656bec'::uuid, '28eba4b8-caa3-56a7-a1f7-59d5e7215c22'::uuid, 'Confier la paie à un cabinet extérieur, c’est…', 'mcq', '["Internaliser","Externaliser","Recruter","Licencier"]'::jsonb, 1, 'On fait faire par un prestataire : souplesse, mais dépendance.', 6),
    ('24306ab4-d16e-53b5-acad-b5046f0aa890'::uuid, '28eba4b8-caa3-56a7-a1f7-59d5e7215c22'::uuid, 'Un micro-entrepreneur est lié à ses clients par un contrat de travail.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est indépendant : pas de lien de subordination, pas de contrat de travail.', 7),
    ('588ec97c-319a-5339-a1ab-9329dd774835'::uuid, '28eba4b8-caa3-56a7-a1f7-59d5e7215c22'::uuid, 'À quoi servent les cotisations sociales ?', 'mcq', '["À rembourser les emprunts de l’entreprise","À financer la publicité","À financer la protection sociale (santé, retraite, chômage)","À payer les dividendes"]'::jsonb, 2, 'Salariales et patronales, elles financent les risques sociaux.', 8),
    ('f5e8116e-e4c8-5eaf-b537-3df2614b13d1'::uuid, '28eba4b8-caa3-56a7-a1f7-59d5e7215c22'::uuid, 'Pourquoi de mauvaises conditions de travail coûtent-elles cher ?', 'mcq', '["Elles augmentent absentéisme, rotation du personnel et erreurs","Elles réduisent les impôts","Elles augmentent automatiquement la productivité","Elles n’ont aucun effet"]'::jsonb, 0, 'Recruter, former et remplacer ont un coût élevé.', 9),
    ('a23c68de-adb6-5bdb-931d-2a2a1f831d49'::uuid, '28eba4b8-caa3-56a7-a1f7-59d5e7215c22'::uuid, 'L’approche par les compétences est rattachée…', 'mcq', '["Au diplôme uniquement","Au fournisseur","Au poste uniquement","À l’individu"]'::jsonb, 3, 'Elle évalue ce que la personne mobilise réellement.', 10),
    ('ae0dd881-0f70-5769-9129-124fcf3f5f4a'::uuid, '28eba4b8-caa3-56a7-a1f7-59d5e7215c22'::uuid, 'Un salarié mieux payé peut coûter moins cher par unité produite s’il est plus productif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le coût du travail se juge rapporté à la production.', 11),
    ('debb6b39-da35-544f-b874-0b0cb677e7c1'::uuid, '28eba4b8-caa3-56a7-a1f7-59d5e7215c22'::uuid, 'Un tableau de bord social regroupe…', 'mcq', '["Les plans des locaux","Des indicateurs sur le personnel (effectif, absentéisme, rotation)","Uniquement le chiffre d’affaires","Les prix des concurrents"]'::jsonb, 1, 'Il aide la GRH à piloter l’activité de travail.', 12),
    ('d4dc8bf2-11ef-53f0-8ee9-b680383e1717'::uuid, 'e5972441-d9e9-5cca-bdb6-23241dfc786b'::uuid, 'Quelle est la différence entre une donnée et une information ?', 'mcq', '["L’information est toujours chiffrée","Aucune","L’information est une donnée mise en forme et en contexte, qui a un sens","La donnée est toujours plus précise"]'::jsonb, 2, 'Une donnée brute n’a pas de sens tant qu’elle n’est pas contextualisée.', 1),
    ('4e427868-14d3-5a0f-8866-8528062d450c'::uuid, 'e5972441-d9e9-5cca-bdb6-23241dfc786b'::uuid, '« Les ventes baissent à cause de la hausse des prix : il faut revoir la tarification » relève de…', 'mcq', '["La connaissance","Le bruit","La donnée","L’information"]'::jsonb, 0, 'C’est une information interprétée qui permet d’agir.', 2),
    ('95933b41-3c4d-5e97-bf9d-7cdfc6242ff8'::uuid, 'e5972441-d9e9-5cca-bdb6-23241dfc786b'::uuid, 'Laquelle est une donnée à caractère personnel ?', 'mcq', '["Le prix d’un produit","Le nombre de magasins d’une enseigne","La température moyenne en juillet","L’adresse électronique d’un client"]'::jsonb, 3, 'Elle permet d’identifier une personne.', 3),
    ('8ab358b6-35dd-5298-bd29-d5f965fd6127'::uuid, 'e5972441-d9e9-5cca-bdb6-23241dfc786b'::uuid, 'Que signifie le principe de minimisation du RGPD ?', 'mcq', '["Collecter le plus de données possible","Ne collecter que les données nécessaires à la finalité","Supprimer toutes les données chaque jour","Réduire la taille des fichiers"]'::jsonb, 1, 'On ne collecte que ce qui sert la finalité annoncée.', 4),
    ('3c21a53d-99bb-5d24-8059-d52bdc2ba279'::uuid, 'e5972441-d9e9-5cca-bdb6-23241dfc786b'::uuid, 'Quelle autorité contrôle en France le respect de la protection des données ?', 'mcq', '["La Banque de France","L’URSSAF","La CNIL","L’INSEE"]'::jsonb, 2, 'La Commission nationale de l’informatique et des libertés peut contrôler et sanctionner.', 5),
    ('c3bac2de-123b-5141-8ee6-10913e2af320'::uuid, 'e5972441-d9e9-5cca-bdb6-23241dfc786b'::uuid, 'Les données ouvertes (open data) sont…', 'mcq', '["Des données mises à disposition librement et réutilisables","Des données personnelles vendues","Des données effacées","Des données secrètes des entreprises"]'::jsonb, 0, 'Horaires de transports, qualité de l’air : chacun peut les réutiliser.', 6),
    ('9803aa73-e890-5d0c-9643-287c968c5984'::uuid, 'e5972441-d9e9-5cca-bdb6-23241dfc786b'::uuid, 'Le système d’information se réduit à l’informatique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il comprend aussi des personnes et des procédures.', 7),
    ('d8bf157a-97ef-5f0f-8ff1-226f2572a934'::uuid, 'e5972441-d9e9-5cca-bdb6-23241dfc786b'::uuid, 'Quelles sont les quatre fonctions du système d’information ?', 'mcq', '["Recruter, former, payer, licencier","Emprunter, investir, rembourser, épargner","Acheter, produire, vendre, livrer","Collecter, mémoriser, traiter, diffuser"]'::jsonb, 3, 'Ce sont les fonctions qui transforment les données en informations utiles.', 8),
    ('d75612c0-0acc-5c9b-8c0d-cf652bb854e8'::uuid, 'e5972441-d9e9-5cca-bdb6-23241dfc786b'::uuid, 'Une information exacte mais arrivée trop tard…', 'mcq', '["Garde toute sa valeur","Perd sa valeur pour la décision","Devient une donnée personnelle","Est automatiquement effacée"]'::jsonb, 1, 'L’actualité fait partie des qualités qui font la valeur de l’information.', 9),
    ('091c5f47-6e51-5b39-964e-8d0b5f943e95'::uuid, 'e5972441-d9e9-5cca-bdb6-23241dfc786b'::uuid, 'Qu’appelle-t-on mégadonnées (big data) ?', 'mcq', '["Un logiciel de traitement de texte","Des fichiers imprimés","Des volumes énormes de données variées produites à grande vitesse","Les données d’une seule personne"]'::jsonb, 2, 'Leur analyse permet de repérer des tendances invisibles à petite échelle.', 10),
    ('2e1a58e2-40aa-51d8-bfe5-da953889bb0c'::uuid, 'e5972441-d9e9-5cca-bdb6-23241dfc786b'::uuid, 'Le RGPD reconnaît aux personnes un droit d’accès et d’effacement de leurs données.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Accès, rectification, effacement, opposition, portabilité font partie de leurs droits.', 11),
    ('725c933a-3991-59ec-8cd9-748afcfe0b39'::uuid, 'e5972441-d9e9-5cca-bdb6-23241dfc786b'::uuid, 'La lecture d’un code-barres en caisse correspond à quelle fonction du SI ?', 'mcq', '["Collecter","Diffuser","Traiter","Archiver"]'::jsonb, 0, 'C’est la saisie de la donnée à la source.', 12),
    ('cfe738d0-ddc3-5520-bf50-0134a29e533f'::uuid, '8ff9cb40-010d-56d6-a755-e33b16c941c5'::uuid, 'Qu’est-ce que l’intelligence collective ?', 'mcq', '["Un logiciel d’intelligence artificielle","Le QI moyen d’une équipe","La somme des diplômes des salariés","La capacité d’un groupe à produire mieux que chacun seul grâce à la mise en commun"]'::jsonb, 3, 'Elle naît de la coopération et du partage d’information.', 1),
    ('97bd8f1a-a9dc-53d0-8a66-de4ebd8b71c5'::uuid, '8ff9cb40-010d-56d6-a755-e33b16c941c5'::uuid, 'Un document que plusieurs personnes modifient en même temps en ligne illustre…', 'mcq', '["La sous-traitance","La collaboration","L’externalisation","La comptabilité"]'::jsonb, 1, 'La co-édition est un usage typique de collaboration.', 2),
    ('87c17e13-07ab-5343-9096-da1d9bc88e28'::uuid, '8ff9cb40-010d-56d6-a755-e33b16c941c5'::uuid, 'Dans un ENT, le rôle de « lecteur » permet en général…', 'mcq', '["D’administrer le serveur","De tout supprimer","De consulter sans modifier","De changer les droits des autres"]'::jsonb, 2, 'Les droits sont attribués selon le rôle.', 3),
    ('42971599-0084-5873-b7ee-e4c3996d7047'::uuid, '8ff9cb40-010d-56d6-a755-e33b16c941c5'::uuid, 'Pourquoi gérer finement les droits d’accès ?', 'mcq', '["Pour éviter fuites d’information et suppressions accidentelles","Pour ralentir le travail","Pour empêcher toute collaboration","Parce que c’est décoratif"]'::jsonb, 0, 'Chacun n’accède qu’à ce dont il a besoin.', 4),
    ('17d10162-94c7-50d6-bbac-46f33c68827e'::uuid, '8ff9cb40-010d-56d6-a755-e33b16c941c5'::uuid, 'Quelle est une condition de l’intelligence collective ?', 'mcq', '["L’absence de règles","Des profils tous identiques","La méfiance entre membres","Un objectif partagé et la confiance"]'::jsonb, 3, 'La diversité des profils est aussi un atout.', 5),
    ('07faeb07-0ae4-547a-8ba1-f2bd2481eb7f'::uuid, '8ff9cb40-010d-56d6-a755-e33b16c941c5'::uuid, 'Un agent conversationnel qui répond aux questions simples des clients est un exemple…', 'mcq', '["D’archivage papier","D’automatisation par l’IA","De communauté en ligne","De réseau social grand public"]'::jsonb, 1, 'L’IA automatise des tâches répétitives.', 6),
    ('2447c8be-363a-5d82-9119-826ce2044c0a'::uuid, '8ff9cb40-010d-56d6-a755-e33b16c941c5'::uuid, 'L’intelligence artificielle ne commet jamais d’erreur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle peut se tromper, inventer des réponses ou reproduire des biais : il faut la contrôler.', 7),
    ('cbbe60cf-73ed-5d11-9ed2-418e1ebc6f6a'::uuid, '8ff9cb40-010d-56d6-a755-e33b16c941c5'::uuid, 'Un forum où les clients se dépannent entre eux est…', 'mcq', '["Un tableau de bord","Une messagerie interne","Une communauté en ligne","Un progiciel de gestion intégré"]'::jsonb, 2, 'Les communautés en ligne mutualisent les savoirs des utilisateurs.', 8),
    ('e4890561-8891-560b-bd23-c5e99779dc23'::uuid, '8ff9cb40-010d-56d6-a755-e33b16c941c5'::uuid, 'Quel risque l’IA fait-elle peser sur l’organisation du travail ?', 'mcq', '["La transformation ou la suppression de certains emplois","La disparition de l’électricité","L’interdiction du télétravail","La hausse obligatoire des salaires"]'::jsonb, 0, 'Certaines tâches disparaissent, d’autres apparaissent : il faut accompagner les salariés.', 9),
    ('8e027fe3-a0e7-504d-8e49-3de75ffc6e40'::uuid, '8ff9cb40-010d-56d6-a755-e33b16c941c5'::uuid, 'Comment l’Union européenne encadre-t-elle l’IA ?', 'mcq', '["Elle ne l’encadre pas","Par une taxe unique sur les robots","Elle l’interdit totalement","Par un règlement qui classe les systèmes selon leur niveau de risque"]'::jsonb, 3, 'Le règlement européen sur l’IA impose des obligations croissantes avec le risque.', 10),
    ('70d4cda9-50b6-50a4-91ce-742b86e781f5'::uuid, '8ff9cb40-010d-56d6-a755-e33b16c941c5'::uuid, 'Un wiki d’entreprise sert surtout à…', 'mcq', '["Contrôler les absences","Partager et mettre à jour des connaissances communes","Calculer la paie","Vendre en ligne"]'::jsonb, 1, 'Chacun peut contribuer à une base de connaissances à jour.', 11),
    ('c463450d-eb5b-5a81-a5de-5ca9331bc788'::uuid, '8ff9cb40-010d-56d6-a755-e33b16c941c5'::uuid, 'Protéger son mot de passe fait partie des responsabilités de l’utilisateur d’un environnement numérique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Droits et responsabilités vont ensemble.', 12),
    ('2c953990-aa42-50c8-8130-0ee5495f12a0'::uuid, 'e7cffea4-d560-51e2-8dad-07e56573cf79'::uuid, 'Qu’est-ce qu’un processus ?', 'mcq', '["Un organigramme","Un logiciel de comptabilité","Un enchaînement d’activités qui produit un résultat à partir d’un événement déclencheur","Un procès devant le tribunal"]'::jsonb, 2, 'Il part d’un déclencheur et aboutit à un résultat pour un client.', 1),
    ('0fa442f7-b2d0-59b2-bed4-141a40ab94e8'::uuid, 'e7cffea4-d560-51e2-8dad-07e56573cf79'::uuid, 'Quel est le principal avantage d’un PGI ?', 'mcq', '["Une donnée saisie une seule fois est disponible dans tous les services","Il est gratuit","Il supprime tout besoin de formation","Chaque service a sa propre base de données séparée"]'::jsonb, 0, 'La base de données commune garantit cohérence et rapidité.', 2),
    ('01a2eb09-e342-57dc-b51f-2f6992fdc491'::uuid, 'e7cffea4-d560-51e2-8dad-07e56573cf79'::uuid, 'Que signifie PGI ?', 'mcq', '["Programme de gestion interne","Protocole global d’information","Plan général d’investissement","Progiciel de gestion intégré"]'::jsonb, 3, 'En anglais : ERP (Enterprise Resource Planning).', 3),
    ('ad7c29a1-94bf-5705-82fb-b153aa497746'::uuid, 'e7cffea4-d560-51e2-8dad-07e56573cf79'::uuid, 'Quel est un risque de l’informatique en nuage ?', 'mcq', '["L’accès depuis n’importe où","La dépendance au prestataire et à la connexion","Les mises à jour automatiques","L’absence d’investissement lourd"]'::jsonb, 1, 'Sans connexion ou si le prestataire faillit, l’activité est bloquée.', 4),
    ('2d41b550-19c8-54fd-9c83-4f98d7c6a4a9'::uuid, 'e7cffea4-d560-51e2-8dad-07e56573cf79'::uuid, 'Un logiciel spécialisé pour gérer une pharmacie est…', 'mcq', '["Une donnée ouverte","Un tableur","Une application métier","Un réseau social"]'::jsonb, 2, 'Il répond aux besoins propres d’un secteur.', 5),
    ('ef58ef1d-dbb8-5e08-b0fb-8ae77af93cb0'::uuid, 'e7cffea4-d560-51e2-8dad-07e56573cf79'::uuid, 'L’automatisation transforme le rôle du comptable : il saisit moins et contrôle, analyse et conseille davantage.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’automatisation déplace le travail vers des tâches à plus forte valeur.', 6),
    ('05eef0b3-8f9c-5483-81b7-7de189962757'::uuid, 'e7cffea4-d560-51e2-8dad-07e56573cf79'::uuid, 'Quand le numérique rigidifie-t-il l’organisation ?', 'mcq', '["Quand on adapte le travail au logiciel au lieu de l’inverse","Quand il supprime les doubles saisies","Quand il accélère l’information","Quand il fluidifie les processus"]'::jsonb, 0, 'Des procédures standardisées peuvent enfermer les acteurs.', 7),
    ('64181744-3262-50e7-b42a-db74b6ab2e94'::uuid, 'e7cffea4-d560-51e2-8dad-07e56573cf79'::uuid, 'Une plateforme où plusieurs vendeurs proposent leurs produits s’appelle…', 'mcq', '["Un PGI","Un intranet","Un wiki","Un site de marché (place de marché)"]'::jsonb, 3, 'Le site de marché met en relation de nombreux vendeurs et acheteurs.', 8),
    ('423896f5-8c7b-54af-a8c6-4ded4e99efe6'::uuid, 'e7cffea4-d560-51e2-8dad-07e56573cf79'::uuid, 'Quel est un risque du télétravail ?', 'mcq', '["La réduction des trajets","L’isolement et le brouillage entre vie privée et vie professionnelle","La souplesse des horaires","L’usage d’outils en ligne"]'::jsonb, 1, 'Il faut organiser le lien avec l’équipe et le droit à la déconnexion.', 9),
    ('eb5dde08-b258-5ab2-a137-d10001752912'::uuid, 'e7cffea4-d560-51e2-8dad-07e56573cf79'::uuid, 'Dans un schéma de processus, « paiement accepté ? oui / non » représente…', 'mcq', '["Un résultat final","Un stock","Une décision (un choix)","Un acteur"]'::jsonb, 2, 'Les décisions orientent la suite du processus.', 10),
    ('9e946ed6-912f-5d70-8379-aea57b2c0b41'::uuid, 'e7cffea4-d560-51e2-8dad-07e56573cf79'::uuid, 'Le cloud computing impose toujours d’acheter ses propres serveurs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Au contraire, les ressources sont hébergées chez un prestataire, souvent par abonnement.', 11),
    ('afddeaa3-a4f4-53c4-b16b-f57cb00d3751'::uuid, 'e7cffea4-d560-51e2-8dad-07e56573cf79'::uuid, 'Quel est un inconvénient d’un PGI ?', 'mcq', '["Un coût d’acquisition et de paramétrage élevé","La cohérence des données","L’automatisation","La traçabilité des opérations"]'::jsonb, 0, 'Il faut aussi former les utilisateurs et on dépend de l’éditeur.', 12),
    ('40ff2a2c-29cc-56c2-b40b-c26dc6fdbe7d'::uuid, 'f703b874-cb6d-5c6f-ab92-3ef30d2ce002'::uuid, 'Comment calcule-t-on la valeur ajoutée ?', 'mcq', '["Salaires + impôts","Bénéfice − dividendes","Chiffre d’affaires + consommations intermédiaires","Chiffre d’affaires − consommations intermédiaires"]'::jsonb, 3, 'C’est la richesse créée par l’entreprise elle-même.', 1),
    ('0efa0e41-2cda-5fb6-9f22-7528e5af53c6'::uuid, 'f703b874-cb6d-5c6f-ab92-3ef30d2ce002'::uuid, 'Un chiffre d’affaires de 500 000 € et 200 000 € de consommations intermédiaires donnent une valeur ajoutée de…', 'mcq', '["700 000 €","300 000 €","200 000 €","2,5"]'::jsonb, 1, '500 000 − 200 000 = 300 000 €.', 2),
    ('cde0274f-ac8f-5365-a711-53c98d511aab'::uuid, 'f703b874-cb6d-5c6f-ab92-3ef30d2ce002'::uuid, 'Lequel est une consommation intermédiaire ?', 'mcq', '["L’impôt sur les sociétés","Le salaire d’un employé","L’électricité consommée par l’atelier","Le dividende versé"]'::jsonb, 2, 'L’énergie est achetée à une autre entreprise et consommée dans la production.', 3),
    ('223817fd-da21-526b-990f-463fda4bb6af'::uuid, 'f703b874-cb6d-5c6f-ab92-3ef30d2ce002'::uuid, 'Sous quelle forme les banques reçoivent-elles une part de la valeur ajoutée ?', 'mcq', '["Des intérêts","Des salaires","Des taxes","Des dividendes"]'::jsonb, 0, 'Les prêteurs sont rémunérés par les intérêts.', 4),
    ('38016367-3259-5903-8f5f-44a41d5a2f2f'::uuid, 'f703b874-cb6d-5c6f-ab92-3ef30d2ce002'::uuid, 'La valeur perçue concerne surtout…', 'mcq', '["L’administration fiscale","Les banques","Les actionnaires","Les clients"]'::jsonb, 3, 'Image, notoriété, satisfaction, avis et réputation la traduisent.', 5),
    ('fcfbd8c6-6577-523f-a1cf-d485f36899ca'::uuid, 'f703b874-cb6d-5c6f-ab92-3ef30d2ce002'::uuid, 'Que présente le bilan ?', 'mcq', '["L’activité de l’année","Le patrimoine de l’entreprise à une date donnée","Les salaires du mois","Le planning de production"]'::jsonb, 1, 'Actif : ce qu’elle possède ; passif : comment c’est financé.', 6),
    ('b0a5c2d0-330f-5880-8390-cec24e180503'::uuid, 'f703b874-cb6d-5c6f-ab92-3ef30d2ce002'::uuid, 'Le compte de résultat permet de calculer…', 'mcq', '["Le nombre de salariés","La capitalisation boursière","Le bénéfice ou la perte de l’année","La valeur des bâtiments"]'::jsonb, 2, 'Produits − charges = résultat.', 7),
    ('42ed42ca-f41f-5aee-8008-28b4e74128ec'::uuid, 'f703b874-cb6d-5c6f-ab92-3ef30d2ce002'::uuid, 'La valeur partenariale prend en compte les attentes de toutes les parties prenantes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Salariés, fournisseurs, clients, territoire : pas seulement les actionnaires.', 8),
    ('363d60a3-d57c-588e-ba5d-1791c3b58ece'::uuid, 'f703b874-cb6d-5c6f-ab92-3ef30d2ce002'::uuid, 'Un produit coûte 12 € et se vend 15 €. Quelle est la marge unitaire ?', 'mcq', '["27 €","3 €","12 €","1,25 €"]'::jsonb, 1, 'Marge = prix de vente − coût = 15 − 12 = 3 €.', 9),
    ('b642fda3-4f56-5e16-b9fe-1076b60602d8'::uuid, 'f703b874-cb6d-5c6f-ab92-3ef30d2ce002'::uuid, 'Quelle part de la valeur ajoutée permet à l’entreprise de s’autofinancer ?', 'mcq', '["Les impôts","Les intérêts","Les dividendes","Le bénéfice mis en réserve"]'::jsonb, 3, 'Ce qui reste dans l’entreprise finance ses investissements futurs.', 10),
    ('66a67bdd-4145-5f59-a06e-b4a7f4215d4d'::uuid, 'f703b874-cb6d-5c6f-ab92-3ef30d2ce002'::uuid, 'La valeur boursière d’une société cotée correspond à…', 'mcq', '["Son chiffre d’affaires","Le cours de l’action multiplié par le nombre d’actions","Le total de ses salaires","Sa valeur ajoutée"]'::jsonb, 1, 'C’est la capitalisation boursière.', 11),
    ('78a085f1-de59-5f3e-aed4-78211a647e21'::uuid, 'f703b874-cb6d-5c6f-ab92-3ef30d2ce002'::uuid, 'Augmenter les dividendes réduit forcément toutes les autres parts de la valeur ajoutée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Si la valeur ajoutée augmente, toutes les parts peuvent croître ; à valeur ajoutée constante, c’est un arbitrage.', 12),
    ('5d67463a-6ae7-50dd-bcff-e94de0524cf8'::uuid, 'a5806844-9f1e-53bd-90a2-f8e058752f1a'::uuid, 'L’efficacité mesure…', 'mcq', '["Le nombre de salariés","Le rapport entre résultats et moyens","Le degré d’atteinte de l’objectif","Le chiffre d’affaires"]'::jsonb, 2, 'Efficace : l’objectif est atteint. Efficient : il l’est avec peu de moyens.', 1),
    ('343d5a46-eb92-5d11-858d-7752ff778f4d'::uuid, 'a5806844-9f1e-53bd-90a2-f8e058752f1a'::uuid, 'Livrer autant de colis avec 10 % de carburant en moins améliore…', 'mcq', '["L’efficience","La part de marché","La valeur boursière","L’efficacité seulement"]'::jsonb, 0, 'Même résultat, moins de moyens : c’est l’efficience.', 2),
    ('3eb32ebf-edb1-5dc2-bef0-d8aba3fdee26'::uuid, 'a5806844-9f1e-53bd-90a2-f8e058752f1a'::uuid, 'Ventes de l’entreprise 3 M€, marché total 30 M€. Quelle est sa part de marché ?', 'mcq', '["3 %","10 %","30 %","90 %"]'::jsonb, 1, '3 ÷ 30 × 100 = 10 %.', 3),
    ('40bea532-4104-5dc6-96a3-8b72075cde99'::uuid, 'a5806844-9f1e-53bd-90a2-f8e058752f1a'::uuid, 'Résultat 50 000 €, chiffre d’affaires 1 000 000 €. Quel est le taux de profitabilité ?', 'mcq', '["0,5 %","5 %","20 %","50 %"]'::jsonb, 1, '50 000 ÷ 1 000 000 × 100 = 5 %.', 4),
    ('2fea6149-dc71-5491-81c4-2a7770cb4215'::uuid, 'a5806844-9f1e-53bd-90a2-f8e058752f1a'::uuid, 'La rentabilité financière rapporte le résultat…', 'mcq', '["Aux stocks","Au chiffre d’affaires","Aux capitaux propres","Aux salaires"]'::jsonb, 2, 'Elle mesure ce que rapporte chaque euro investi par les associés.', 5),
    ('1f5162d9-050f-5ba1-abc7-c1a848ceda72'::uuid, 'a5806844-9f1e-53bd-90a2-f8e058752f1a'::uuid, 'Quel document présente les indicateurs de la performance sociale ?', 'mcq', '["Le bilan social","Le bilan comptable","Le compte de résultat","La facture"]'::jsonb, 0, 'Effectifs, absentéisme, accidents, formation, égalité y figurent.', 6),
    ('947c6fcc-0c93-5eae-965e-c89417d9a6b3'::uuid, 'a5806844-9f1e-53bd-90a2-f8e058752f1a'::uuid, 'Les émissions de CO2 d’une usine sont un indicateur de performance…', 'mcq', '["Financière","Sociale","Commerciale","Environnementale"]'::jsonb, 3, 'Déchets, eau, énergie, émissions mesurent l’impact environnemental.', 7),
    ('4e8bb87c-791f-5da9-8308-c7a67344a6d5'::uuid, 'a5806844-9f1e-53bd-90a2-f8e058752f1a'::uuid, 'Baisser ses prix pour gagner des parts de marché peut réduire la profitabilité.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un exemple de performances contradictoires.', 8),
    ('ccaeb30c-4f58-5506-b8d2-b43682db4c83'::uuid, 'a5806844-9f1e-53bd-90a2-f8e058752f1a'::uuid, 'Le taux de fidélité des clients est un indicateur de performance…', 'mcq', '["Fiscale","Commerciale","Sociale","Environnementale"]'::jsonb, 1, 'Chiffre d’affaires, part de marché et fidélité mesurent la performance commerciale.', 9),
    ('fd85fc57-7f51-5c1c-92a1-1175d6a260fc'::uuid, 'a5806844-9f1e-53bd-90a2-f8e058752f1a'::uuid, 'Pourquoi comparer les indicateurs dans l’espace ?', 'mcq', '["Parce que la loi l’impose","Pour éviter de comparer dans le temps","Pour situer l’organisation par rapport à ses concurrents ou au secteur","Pour décorer le tableau de bord"]'::jsonb, 2, 'Un chiffre isolé ne dit pas si l’on fait mieux ou moins bien que les autres.', 10),
    ('f0fc3800-30db-50cb-aa2d-a7a94fc751bb'::uuid, 'a5806844-9f1e-53bd-90a2-f8e058752f1a'::uuid, 'Une organisation peut être efficace sans être efficiente.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle atteint l’objectif mais en gaspillant des ressources.', 11),
    ('cca87192-ffd7-57df-8507-716888b585ee'::uuid, 'a5806844-9f1e-53bd-90a2-f8e058752f1a'::uuid, 'Distribuer davantage de dividendes a pour effet de…', 'mcq', '["Réduire l’autofinancement","Augmenter la part de marché","Réduire l’absentéisme","Augmenter l’autofinancement"]'::jsonb, 0, 'Ce qui est distribué ne reste pas dans l’entreprise pour investir.', 12),
    ('c15be83b-db10-5a4a-8035-ecb5ce59e0b9'::uuid, 'e09d2865-ddf1-5af9-a837-1f2f3ac41f81'::uuid, 'Quel horizon correspond à la stratégie d’une organisation ?', 'mcq', '["Le mois en cours","Aucun horizon","Le très court terme (une journée)","Le long terme"]'::jsonb, 3, 'La stratégie engage l’avenir sur plusieurs années.', 1),
    ('b99e7fc9-0d7b-546f-a34c-2e98e0fc859b'::uuid, 'e09d2865-ddf1-5af9-a837-1f2f3ac41f81'::uuid, 'Le loyer d’un magasin est une charge…', 'mcq', '["Variable","Fixe","Exceptionnelle","Intermédiaire uniquement"]'::jsonb, 1, 'Il ne dépend pas du volume des ventes à court terme.', 2),
    ('36c52ae1-220c-5645-bca6-c79ca1c0e3d8'::uuid, 'e09d2865-ddf1-5af9-a837-1f2f3ac41f81'::uuid, 'Charges fixes 20 000 €, taux de marge sur coût variable 25 %. Seuil de rentabilité ?', 'mcq', '["5 000 €","25 000 €","80 000 €","200 000 €"]'::jsonb, 2, '20 000 ÷ 0,25 = 80 000 €.', 3),
    ('75cf0192-4d36-589a-bcc6-b57d6f6bda14'::uuid, 'e09d2865-ddf1-5af9-a837-1f2f3ac41f81'::uuid, 'Que représente le seuil de rentabilité ?', 'mcq', '["Le chiffre d’affaires pour lequel le résultat est nul","Le bénéfice de l’année","Le total des charges variables","Le chiffre d’affaires maximal"]'::jsonb, 0, 'Au-delà, chaque vente supplémentaire dégage du bénéfice.', 4),
    ('917232e0-bf55-5b85-848c-7583eafbee8f'::uuid, 'e09d2865-ddf1-5af9-a837-1f2f3ac41f81'::uuid, 'Un produit vendu 20 € avec 12 € de charges variables a une marge sur coût variable unitaire de…', 'mcq', '["32 €","8 €","12 €","40 %"]'::jsonb, 1, '20 − 12 = 8 € (soit un taux de 40 %).', 5),
    ('d7547673-e1a3-558b-81b6-623be346b23f'::uuid, 'e09d2865-ddf1-5af9-a837-1f2f3ac41f81'::uuid, 'À quoi sert le budget de trésorerie ?', 'mcq', '["À calculer la valeur ajoutée","À prévoir mois par mois encaissements et décaissements","À fixer les salaires","À choisir un logo"]'::jsonb, 1, 'Il permet d’anticiper un manque ou un excédent de trésorerie.', 6),
    ('d97109f9-5d17-5ce7-93c7-93b373fce07f'::uuid, 'e09d2865-ddf1-5af9-a837-1f2f3ac41f81'::uuid, '1 000 € placés à 5 % pendant un an deviennent…', 'mcq', '["1 005 €","1 050 €","1 500 €","1 100 €"]'::jsonb, 1, '1 000 × 1,05 = 1 050 €.', 7),
    ('7239c81b-9b88-529d-9e09-49f77efa52eb'::uuid, 'e09d2865-ddf1-5af9-a837-1f2f3ac41f81'::uuid, 'Un euro disponible aujourd’hui vaut plus qu’un euro dans un an.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On peut le placer et percevoir des intérêts : c’est le lien entre temps et valeur financière.', 8),
    ('68236e6c-9ff1-581a-8361-589115602f42'::uuid, 'e09d2865-ddf1-5af9-a837-1f2f3ac41f81'::uuid, 'Qu’est-ce que la veille informationnelle ?', 'mcq', '["La surveillance continue des sources pour disposer d’informations à jour","L’archivage des factures","Le contrôle des horaires","Une réunion de fin d’année"]'::jsonb, 0, 'Une information périmée conduit à de mauvaises décisions.', 9),
    ('3f7b258e-248c-5589-81a5-ff2c6ffb977a'::uuid, 'e09d2865-ddf1-5af9-a837-1f2f3ac41f81'::uuid, 'Qu’appelle-t-on asymétrie d’information ?', 'mcq', '["Une erreur de calcul","Une information chiffrée","Une information partagée par tous","Une situation où un acteur en sait plus qu’un autre"]'::jsonb, 3, 'Elle peut fausser les décisions et les négociations.', 10),
    ('5865fdde-fdf3-5e85-a93b-11775db78179'::uuid, 'e09d2865-ddf1-5af9-a837-1f2f3ac41f81'::uuid, 'Plus l’horizon de prévision est lointain, plus l’information est certaine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : l’incertitude augmente avec l’horizon.', 11),
    ('01b0dbcc-8a15-5d9c-aae3-ede8bab9407c'::uuid, 'e09d2865-ddf1-5af9-a837-1f2f3ac41f81'::uuid, 'L’exercice comptable d’un an est une contrainte de découpage du temps…', 'mcq', '["Personnelle","Institutionnelle","Sectorielle","Météorologique"]'::jsonb, 1, 'Elle est imposée par la loi et les règles comptables.', 12),
    ('1ed5eed2-d6be-5917-b07b-cffb7b05088b'::uuid, '0f5d2dce-5be1-575b-b718-7124ab41c0c8'::uuid, 'Comment évalue-t-on le niveau d’un risque ?', 'mcq', '["Nombre de salariés ÷ effectif","Prix × quantité","Probabilité × gravité","Chiffre d’affaires − charges"]'::jsonb, 2, 'On croise la chance qu’il survienne et l’ampleur de ses conséquences.', 1),
    ('77b5a08e-912c-5591-9c42-23c7aea9d241'::uuid, '0f5d2dce-5be1-575b-b718-7124ab41c0c8'::uuid, 'Souscrire une assurance, c’est…', 'mcq', '["Transférer le risque","Accepter le risque","Créer un risque","Éviter le risque"]'::jsonb, 0, 'Les conséquences financières sont transférées à l’assureur.', 2),
    ('ad9f5885-d7d9-5e17-af7a-86a9e25dbe6f'::uuid, '0f5d2dce-5be1-575b-b718-7124ab41c0c8'::uuid, 'Diversifier ses fournisseurs permet de…', 'mcq', '["Supprimer toute concurrence","Augmenter la dépendance","Éviter de payer la TVA","Réduire le risque d’approvisionnement"]'::jsonb, 3, 'Si un fournisseur fait défaut, un autre prend le relais.', 3),
    ('991f145c-a066-50d6-ab58-3a4a4db767ca'::uuid, '0f5d2dce-5be1-575b-b718-7124ab41c0c8'::uuid, 'Une innovation qui rend un savoir-faire inutile est une…', 'mcq', '["Délocalisation","Rupture technologique","Obsolescence programmée","Asymétrie d’information"]'::jsonb, 1, 'L’appareil photo numérique face à l’argentique en est un exemple classique.', 4),
    ('3ef45e10-80d6-56fb-b340-79771ad66058'::uuid, '0f5d2dce-5be1-575b-b718-7124ab41c0c8'::uuid, 'Un endettement excessif décidé par la direction est un risque…', 'mcq', '["Réglementaire","Externe","Interne","Naturel"]'::jsonb, 2, 'Il naît des décisions de l’organisation elle-même.', 5),
    ('a382583d-bf65-5876-b4b5-629eb56842eb'::uuid, '0f5d2dce-5be1-575b-b718-7124ab41c0c8'::uuid, 'Ne prendre aucun risque garantit la performance durable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’organisation qui n’innove pas se fait dépasser : l’immobilisme est aussi un risque.', 6),
    ('4f7856c3-25a2-51e6-a13a-a1cd51576ea8'::uuid, '0f5d2dce-5be1-575b-b718-7124ab41c0c8'::uuid, 'Quelle est la première étape de la gestion des risques ?', 'mcq', '["Identifier les risques","Souscrire une assurance","Licencier","Traiter les risques"]'::jsonb, 0, 'Identifier, évaluer, traiter, suivre.', 7),
    ('fd701e02-e37a-5c30-9cdf-999c5b046f42'::uuid, '0f5d2dce-5be1-575b-b718-7124ab41c0c8'::uuid, 'La flambée du prix de l’énergie est un facteur de risque lié à…', 'mcq', '["La rétention d’information","La culture d’entreprise","Le leadership","La dépendance énergétique"]'::jsonb, 3, 'C’est un facteur externe que l’organisation subit.', 8),
    ('f65c99a2-9c03-5e94-875e-f0d1cd83c606'::uuid, '0f5d2dce-5be1-575b-b718-7124ab41c0c8'::uuid, 'Une cartographie des risques sert à…', 'mcq', '["Localiser les magasins","Visualiser les risques selon leur probabilité et leur gravité","Dessiner l’organigramme","Calculer la paie"]'::jsonb, 1, 'Elle aide à prioriser les actions.', 9),
    ('d7ad2886-b7db-5b08-a916-425302b11e32'::uuid, '0f5d2dce-5be1-575b-b718-7124ab41c0c8'::uuid, 'Pourquoi la pollution causée par une entreprise finit-elle par peser sur elle ?', 'mcq', '["Elle augmente automatiquement les ventes","Elle réduit ses impôts","Sanctions, coûts de dépollution, boycott, perte d’attractivité","Elle n’a jamais d’effet sur l’entreprise"]'::jsonb, 2, 'Les conséquences écologiques reviennent sous forme de coûts et de risques.', 10),
    ('5b797282-4810-5972-9d39-77121f880fb3'::uuid, '0f5d2dce-5be1-575b-b718-7124ab41c0c8'::uuid, 'Dépendre d’un seul gros client est un facteur de risque.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Si ce client part, une grande part du chiffre d’affaires disparaît.', 11),
    ('943b69cb-b3df-5666-84eb-ecf89e17f4c7'::uuid, '0f5d2dce-5be1-575b-b718-7124ab41c0c8'::uuid, 'Renoncer à entrer sur un marché très instable, c’est…', 'mcq', '["Éviter le risque","Transférer le risque","Accepter le risque","Réduire la probabilité à zéro par assurance"]'::jsonb, 0, 'On supprime l’exposition au risque en renonçant à l’activité.', 12),
    ('9a921093-3c43-54b9-a5e3-abe239de39ec'::uuid, 'c2fef938-7550-57d0-8b6f-c919bc897e45'::uuid, 'Sur quoi porte l’étude de gestion ?', 'mcq', '["Sur un roman étudié en français","Sur l’histoire de l’économie","Sur une organisation imaginaire","Sur une ou plusieurs organisations réelles, à partir d’une question de gestion du programme"]'::jsonb, 3, 'On applique les notions du programme à un cas réel.', 1),
    ('564b070e-d8d3-5bc5-b822-1dc94afbb887'::uuid, 'c2fef938-7550-57d0-8b6f-c919bc897e45'::uuid, 'Quelle est une bonne problématique ?', 'mcq', '["Le magasin X a-t-il un site internet ?","En quoi le click and collect a-t-il rendu le magasin X plus agile ?","Présentation du magasin X","Le numérique dans les entreprises"]'::jsonb, 1, 'Elle est ouverte, précise, reliée au programme et appliquée à l’organisation.', 2),
    ('9a8d31b0-38eb-58b1-b1d7-16974b525c4a'::uuid, 'c2fef938-7550-57d0-8b6f-c919bc897e45'::uuid, 'À quoi sert le carnet de bord ?', 'mcq', '["À recopier le cours","À noter ses notes des autres matières","À retracer sa démarche : sources, contacts, difficultés, choix","À remplacer l’oral"]'::jsonb, 2, 'Il prouve que l’étude est personnelle et aide à l’oral.', 3),
    ('864af070-6dbd-580b-b825-d3b34cdd8aae'::uuid, 'c2fef938-7550-57d0-8b6f-c919bc897e45'::uuid, 'Combien de temps dure en général l’exposé de la soutenance ?', 'mcq', '["Dix minutes au plus","Une heure","Il n’y a pas d’exposé","Deux minutes"]'::jsonb, 0, 'Un exposé de dix minutes au plus, puis un entretien, environ vingt minutes en tout.', 4),
    ('f5a319a3-3e64-5642-bed8-9a51be73134e'::uuid, 'c2fef938-7550-57d0-8b6f-c919bc897e45'::uuid, 'Une étude de gestion purement descriptive est satisfaisante.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut analyser avec les notions du programme, pas seulement décrire.', 5),
    ('795217bf-8166-55e6-ae14-7d981edbf7a4'::uuid, 'c2fef938-7550-57d0-8b6f-c919bc897e45'::uuid, 'Pourquoi croiser au moins deux sources ?', 'mcq', '["Pour allonger le dossier","Parce qu’une seule source est interdite par la loi","Pour éviter de citer ses sources","Pour vérifier la fiabilité des informations"]'::jsonb, 3, 'Une information confirmée par deux sources indépendantes est plus fiable.', 6),
    ('fd3b963b-6e52-518a-a152-05e8cbe446e9'::uuid, 'c2fef938-7550-57d0-8b6f-c919bc897e45'::uuid, 'Quelle est une source interne à l’organisation ?', 'mcq', '["Un article de presse nationale","Un entretien avec un responsable de l’organisation","Une statistique de l’INSEE","Un avis client sur un site extérieur"]'::jsonb, 1, 'Les sources internes émanent de l’organisation elle-même.', 7),
    ('101f2d1d-ff3f-5480-b89b-94f553e03e9c'::uuid, 'c2fef938-7550-57d0-8b6f-c919bc897e45'::uuid, 'Que faut-il faire en conclusion de l’exposé ?', 'mcq', '["Lire la bibliographie","Remercier sans conclure","Répondre à la problématique, signaler une limite, ouvrir","Recommencer l’introduction"]'::jsonb, 2, 'La conclusion apporte la réponse promise dans l’introduction.', 8),
    ('c8bd2ac2-749a-5c66-9b43-1a2e05f00579'::uuid, 'c2fef938-7550-57d0-8b6f-c919bc897e45'::uuid, 'Que regarde surtout le jury ?', 'mcq', '["Que tu raisonnes avec les notions du programme et que tu expliques ta démarche","La longueur du diaporama","Le nombre de pages du dossier","Que tu connaisses tout sur l’organisation"]'::jsonb, 0, 'L’analyse et la démarche comptent plus que l’exhaustivité.', 9),
    ('77ea596e-ec32-554d-a495-4c5d73bf296f'::uuid, 'c2fef938-7550-57d0-8b6f-c919bc897e45'::uuid, 'Faire rédiger son étude par une IA sans le dire est acceptable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’étude doit être personnelle et les sources citées ; le carnet de bord en témoigne.', 10),
    ('7ed189a8-a2d0-5f6d-881c-86ebeef4a717'::uuid, 'c2fef938-7550-57d0-8b6f-c919bc897e45'::uuid, 'Lors d’un entretien avec un salarié, il faut…', 'mcq', '["Poser uniquement des questions fermées","Publier ses réponses sur les réseaux sociaux","Enregistrer sans prévenir","Préparer des questions ouvertes et respecter la confidentialité"]'::jsonb, 3, 'Préparation, autorisation, remerciement et discrétion.', 11),
    ('6ec9b763-1436-50c8-b041-e5a96f133ad0'::uuid, 'c2fef938-7550-57d0-8b6f-c919bc897e45'::uuid, 'À quoi doit se rattacher le thème de l’étude ?', 'mcq', '["Au règlement intérieur du lycée","À une question de gestion du programme de sciences de gestion et numérique","À n’importe quel sujet d’actualité","Au programme de mathématiques"]'::jsonb, 1, 'La problématique est tirée d’une ou plusieurs questions de gestion du programme.', 12)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('droit-economie', 'droit-economie', 'management', 'management-sgn', 'sciences-gestion-numerique');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('droit-economie', 'droit-economie', 'management', 'management-sgn', 'sciences-gestion-numerique')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 389 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 389 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
